window.REVIEW = {"version":"236","builtAt":"2026-07-25","counts":{"lessons":84,"sentences":503,"vocab":560},"levels":[{"id":"L0","name":"Level 0","title":"First Sounds","lessons":[{"id":"l0-a","section":"The Sounds","title":"あ・い・う・え・お — the first five","grammar":"あ い う え お","grammarNote":"Your first five sounds: あ(a) い(i) う(u) え(e) お(o). Every word here uses only these letters — say each one out loud as you spell it.","vocab":[{"jp":"いえ","romaji":"ie","en":"house","pos":"n"},{"jp":"うえ","romaji":"ue","en":"up / above","pos":"n"},{"jp":"あい","romaji":"ai","en":"love","pos":"n"},{"jp":"いい","romaji":"ii","en":"good","pos":"adj"},{"jp":"あおい","romaji":"aoi","en":"blue","pos":"adj"},{"jp":"ええ","romaji":"ee","en":"yeah (casual yes)","pos":"expr"},{"jp":"いいえ","romaji":"iie","en":"no","pos":"expr"}],"sentences":[{"en":"What a nice house!","jp":"いい いえ！","romaji":"ii ie!","hint":""},{"en":"No.","jp":"いいえ。","romaji":"iie.","hint":""},{"en":"A blue house!","jp":"あおい いえ！","romaji":"aoi ie!","hint":""},{"en":"Up!","jp":"うえ！","romaji":"ue!","hint":""},{"en":"Yeah.","jp":"ええ。","romaji":"ee.","hint":""}]},{"id":"l0-ka","section":"The Sounds","title":"か・き・く・け・こ","grammar":"か き く け こ","grammarNote":"The k-row: か(ka) き(ki) く(ku) け(ke) こ(ko). Ten letters in — real words appear: かお, いけ, こえ…","vocab":[{"jp":"かお","romaji":"kao","en":"face","pos":"n"},{"jp":"いけ","romaji":"ike","en":"pond","pos":"n"},{"jp":"こえ","romaji":"koe","en":"voice","pos":"n"},{"jp":"えき","romaji":"eki","en":"station","pos":"n"},{"jp":"くうき","romaji":"kuuki","en":"air","pos":"n"},{"jp":"あかい","romaji":"akai","en":"red","pos":"adj"},{"jp":"おおきい","romaji":"ookii","en":"big","pos":"adj"}],"sentences":[{"en":"A big face!","jp":"おおきい かお！","romaji":"ookii kao!","hint":""},{"en":"A red face!","jp":"あかい かお！","romaji":"akai kao!","hint":"he's blushing"},{"en":"What a nice voice!","jp":"いい こえ！","romaji":"ii koe!","hint":""},{"en":"A big station!","jp":"おおきい えき！","romaji":"ookii eki!","hint":""},{"en":"Nice fresh air!","jp":"いい くうき！","romaji":"ii kuuki!","hint":""},{"en":"A big pond!","jp":"おおきい いけ！","romaji":"ookii ike!","hint":""}]},{"id":"l0-sa","section":"The Sounds","title":"さ・し・す・せ・そ","grammar":"さ し す せ そ","grammarNote":"The s-row: さ(sa) し(shi — not si!) す(su) せ(se) そ(so). Now you can spell すし.","vocab":[{"jp":"すし","romaji":"sushi","en":"sushi","pos":"n"},{"jp":"あさ","romaji":"asa","en":"morning","pos":"n"},{"jp":"いす","romaji":"isu","en":"chair","pos":"n"},{"jp":"うし","romaji":"ushi","en":"cow","pos":"n"},{"jp":"しお","romaji":"shio","en":"salt","pos":"n"},{"jp":"せかい","romaji":"sekai","en":"the world","pos":"n"},{"jp":"うそ","romaji":"uso","en":"a lie — うそ! = no way!","pos":"expr"},{"jp":"あし","romaji":"ashi","en":"foot / leg","pos":"n"},{"jp":"おいしい","romaji":"oishii","en":"tasty","pos":"adj"}],"sentences":[{"en":"Tasty sushi!","jp":"おいしい すし！","romaji":"oishii sushi!","hint":""},{"en":"A big cow!","jp":"おおきい うし！","romaji":"ookii ushi!","hint":""},{"en":"A big world!","jp":"おおきい せかい！","romaji":"ookii sekai!","hint":""},{"en":"No way!","jp":"うそ！","romaji":"uso!","hint":""},{"en":"A nice morning!","jp":"いい あさ！","romaji":"ii asa!","hint":""}]},{"id":"l0-ta","section":"The Sounds","title":"た・ち・つ・て・と","grammar":"た ち つ て と","grammarNote":"The t-row: た(ta) ち(chi) つ(tsu) て(te) と(to). とけい, たこ — the words get useful fast.","vocab":[{"jp":"とけい","romaji":"tokei","en":"clock","pos":"n"},{"jp":"たこ","romaji":"tako","en":"octopus","pos":"n"},{"jp":"そと","romaji":"soto","en":"outside","pos":"n"},{"jp":"した","romaji":"shita","en":"under / below","pos":"n"},{"jp":"て","romaji":"te","en":"hand","pos":"n"},{"jp":"いつ","romaji":"itsu","en":"when","pos":"expr"},{"jp":"たかい","romaji":"takai","en":"expensive / tall","pos":"adj"},{"jp":"ちいさい","romaji":"chiisai","en":"small","pos":"adj"}],"sentences":[{"en":"An expensive clock!","jp":"たかい とけい！","romaji":"takai tokei!","hint":""},{"en":"A small octopus!","jp":"ちいさい たこ！","romaji":"chiisai tako!","hint":""},{"en":"When?","jp":"いつ？","romaji":"itsu?","hint":""},{"en":"A small hand!","jp":"ちいさい て！","romaji":"chiisai te!","hint":""},{"en":"Tasty octopus!","jp":"おいしい たこ！","romaji":"oishii tako!","hint":""}]},{"id":"l0-na","section":"The Sounds","title":"な・に・ぬ・ね・の","grammar":"な に ぬ ね の  ·  [A]の[B]","grammarNote":"The n-row: な(na) に(ni) ぬ(nu) ね(ne) の(no). And your first grammar: の links two things — ねこの あし is the cat's foot.","vocab":[{"jp":"ねこ","romaji":"neko","en":"cat","pos":"n"},{"jp":"いぬ","romaji":"inu","en":"dog","pos":"n"},{"jp":"なに","romaji":"nani","en":"what","pos":"expr"},{"jp":"にく","romaji":"niku","en":"meat","pos":"n"}],"sentences":[{"en":"The cat's foot!","jp":"ねこの あし！","romaji":"neko no ashi!","hint":""},{"en":"The dog's face!","jp":"いぬの かお！","romaji":"inu no kao!","hint":""},{"en":"What?","jp":"なに？","romaji":"nani?","hint":""},{"en":"The cat's paw!","jp":"ねこの て！","romaji":"neko no te!","hint":""},{"en":"The dog's house!","jp":"いぬの いえ！","romaji":"inu no ie!","hint":""}]},{"id":"l0-ha","section":"The Sounds","title":"は・ひ・ふ・へ・ほ — and は says wa","grammar":"は ひ ふ へ ほ  ·  [A]は [B]","grammarNote":"The h-row: は(ha) ひ(hi) ふ(fu) へ(he) ほ(ho). The star: は — written ha but SAID wa when it marks the topic. はなは あかい — the flower is red. Your first full sentences!","vocab":[{"jp":"はい","romaji":"hai","en":"yes","pos":"expr"},{"jp":"はな","romaji":"hana","en":"flower / nose","pos":"n"},{"jp":"ひと","romaji":"hito","en":"person","pos":"n"},{"jp":"ふね","romaji":"fune","en":"boat","pos":"n"},{"jp":"ほし","romaji":"hoshi","en":"star","pos":"n"},{"jp":"おへそ","romaji":"oheso","en":"belly button","pos":"n"},{"jp":"はし","romaji":"hashi","en":"bridge / chopsticks","pos":"n"},{"jp":"とおい","romaji":"tooi","en":"far","pos":"adj"}],"sentences":[{"en":"The flower is red.","jp":"はなは あかい。","romaji":"hana wa akai.","hint":""},{"en":"The boat is big.","jp":"ふねは おおきい。","romaji":"fune wa ookii.","hint":""},{"en":"The stars are far away.","jp":"ほしは とおい。","romaji":"hoshi wa tooi.","hint":""},{"en":"Yes.","jp":"はい。","romaji":"hai.","hint":""},{"en":"A tiny belly button!","jp":"ちいさい おへそ！","romaji":"chiisai oheso!","hint":""},{"en":"A nice person!","jp":"いい ひと！","romaji":"ii hito!","hint":""}]},{"id":"l0-ma","section":"The Sounds","title":"ま・み・む・め・も","grammar":"ま み む め も","grammarNote":"The m-row: ま(ma) み(mi) む(mu) め(me) も(mo). More は-sentences with everything you own so far.","vocab":[{"jp":"まち","romaji":"machi","en":"town","pos":"n"},{"jp":"もも","romaji":"momo","en":"peach","pos":"n"},{"jp":"みせ","romaji":"mise","en":"shop","pos":"n"},{"jp":"あめ","romaji":"ame","en":"rain / candy","pos":"n"},{"jp":"うみ","romaji":"umi","en":"sea","pos":"n"},{"jp":"むし","romaji":"mushi","en":"insect","pos":"n"},{"jp":"め","romaji":"me","en":"eye","pos":"n"}],"sentences":[{"en":"The sea is blue.","jp":"うみは あおい。","romaji":"umi wa aoi.","hint":""},{"en":"The town is small.","jp":"まちは ちいさい。","romaji":"machi wa chiisai.","hint":""},{"en":"The peach is tasty.","jp":"ももは おいしい。","romaji":"momo wa oishii.","hint":""},{"en":"The bug is small.","jp":"むしは ちいさい。","romaji":"mushi wa chiisai.","hint":""},{"en":"The eyes are big.","jp":"めは おおきい。","romaji":"me wa ookii.","hint":""}]},{"id":"l0-ya","section":"The Sounds","title":"や・ゆ・よ","grammar":"や ゆ よ","grammarNote":"Just three this time: や(ya) ゆ(yu) よ(yo). A gentle day — enjoy the mountain weather.","vocab":[{"jp":"やま","romaji":"yama","en":"mountain","pos":"n"},{"jp":"ふゆ","romaji":"fuyu","en":"winter","pos":"n"},{"jp":"つよい","romaji":"tsuyoi","en":"strong","pos":"adj"},{"jp":"やさい","romaji":"yasai","en":"vegetables","pos":"n"},{"jp":"ゆき","romaji":"yuki","en":"snow","pos":"n"},{"jp":"つめたい","romaji":"tsumetai","en":"cold (to the touch)","pos":"adj"},{"jp":"さむい","romaji":"samui","en":"cold","pos":"adj"}],"sentences":[{"en":"The mountain is tall.","jp":"やまは たかい。","romaji":"yama wa takai.","hint":""},{"en":"Winter is cold.","jp":"ふゆは さむい。","romaji":"fuyu wa samui.","hint":""},{"en":"The vegetables are tasty.","jp":"やさいは おいしい。","romaji":"yasai wa oishii.","hint":""},{"en":"The snow is cold.","jp":"ゆきは つめたい。","romaji":"yuki wa tsumetai.","hint":"つめたい = cold to the touch"},{"en":"A strong cow!","jp":"つよい うし！","romaji":"tsuyoi ushi!","hint":""}]},{"id":"l0-ra","section":"The Sounds","title":"ら・り・る・れ・ろ — これ・それ・あれ","grammar":"ら り る れ ろ  ·  これ・それ・あれ","grammarNote":"The r-row: ら(ra) り(ri) る(ru) れ(re) ろ(ro) — a soft tap between r and l. It unlocks the pointing words: これ (this) and それ (that).","vocab":[{"jp":"これ","romaji":"kore","en":"this","pos":"n"},{"jp":"それ","romaji":"sore","en":"that (by you)","pos":"n"},{"jp":"とり","romaji":"tori","en":"bird","pos":"n"},{"jp":"くるま","romaji":"kuruma","en":"car","pos":"n"},{"jp":"さくら","romaji":"sakura","en":"cherry blossom","pos":"n"},{"jp":"しろい","romaji":"shiroi","en":"white","pos":"adj"}],"sentences":[{"en":"This is a bird. (casual)","jp":"これは とり。","romaji":"kore wa tori.","hint":"casual style — です arrives in the next lesson"},{"en":"That is a car. (casual)","jp":"それは くるま。","romaji":"sore wa kuruma.","hint":""},{"en":"The cherry blossoms are white.","jp":"さくらは しろい。","romaji":"sakura wa shiroi.","hint":""},{"en":"That (over there) is a mountain.","jp":"あれは やま。","romaji":"are wa yama.","hint":""},{"en":"This is a cherry blossom.","jp":"これは さくら。","romaji":"kore wa sakura.","hint":""}]},{"id":"l0-wa","section":"The Sounds","title":"わ・を・ん — meet わたし","grammar":"わ を ん","grammarNote":"The last base letters: わ(wa) を(o — the object marker you'll meet later) ん(n — the only letter with no vowel). わたし is you!","vocab":[{"jp":"わたし","romaji":"watashi","en":"I / me","pos":"n"},{"jp":"ほん","romaji":"hon","en":"book","pos":"n"},{"jp":"にほん","romaji":"nihon","en":"Japan","pos":"n"}],"sentences":[{"en":"My book!","jp":"わたしの ほん！","romaji":"watashi no hon!","hint":""},{"en":"My cat is white.","jp":"わたしの ねこは しろい。","romaji":"watashi no neko wa shiroi.","hint":""},{"en":"Japan is far away.","jp":"にほんは とおい。","romaji":"nihon wa tooi.","hint":""},{"en":"My hand!","jp":"わたしの て！","romaji":"watashi no te!","hint":""},{"en":"My house is small.","jp":"わたしの いえは ちいさい。","romaji":"watashi no ie wa chiisai.","hint":""}]},{"id":"l0-dakuten","section":"The Sounds","title":"てんてん ゛— new sounds from old","grammar":"か→が  た→だ  は→ば・ぱ  ·  です","grammarNote":"Two little marks make new sounds from letters you know: ゛(てんてん) turns か→が(ga), さ→ざ(za), た→だ(da), は→ば(ba); ゜(まる) makes ぱ(pa). And だ-row gives you で — which unlocks です, the polite is/am you'll use everywhere from now on.","vocab":[{"jp":"ともだち","romaji":"tomodachi","en":"friend","pos":"n"},{"jp":"でんわ","romaji":"denwa","en":"telephone","pos":"n"},{"jp":"えいが","romaji":"eiga","en":"movie","pos":"n"},{"jp":"ぱん","romaji":"pan","en":"bread","pos":"n"},{"jp":"まど","romaji":"mado","en":"window","pos":"n"},{"jp":"たのしい","romaji":"tanoshii","en":"fun","pos":"adj"}],"sentences":[{"en":"This is a book.","jp":"これは ほんです。","romaji":"kore wa hon desu.","hint":"your first です — welcome to polite Japanese"},{"en":"The movie is fun.","jp":"えいがは たのしいです。","romaji":"eiga wa tanoshii desu.","hint":""},{"en":"My friend's telephone.","jp":"ともだちの でんわ。","romaji":"tomodachi no denwa.","hint":""},{"en":"The window is big.","jp":"まどは おおきいです。","romaji":"mado wa ookii desu.","hint":""},{"en":"This is bread.","jp":"これは ぱんです。","romaji":"kore wa pan desu.","hint":""}]}]},{"id":"L1","name":"Level 1","title":"Foundations","lessons":[{"id":"intro","section":"First Contact","title":"Hello & Introductions","grammar":"X は Y です  ·  か","grammarNote":"は marks the topic (what you're talking about) — written は (ha) but always SAID wa. です means is/am. Add か at the very end to turn a statement into a question.","vocab":[{"jp":"わたし","romaji":"watashi","en":"I / me","pos":"n"},{"jp":"がくせい","romaji":"gakusei","en":"student","pos":"n"},{"jp":"アメリカじん","romaji":"amerika-jin","en":"American","pos":"n"},{"jp":"ともだち","romaji":"tomodachi","en":"friend","pos":"n"},{"jp":"なまえ","romaji":"namae","en":"name  (お = polite)","pos":"n"},{"jp":"なん","romaji":"nan","en":"what","pos":"n"}],"sentences":[{"en":"Nice to meet you.","jp":"はじめまして。","romaji":"hajimemashite.","hint":""},{"en":"I'm Tom.","jp":"わたしは トムです。","romaji":"watashi wa Tomu desu.","hint":"は marks the topic"},{"en":"I'm American.","jp":"わたしは アメリカじんです。","romaji":"watashi wa amerika-jin desu.","hint":""},{"en":"I'm a student.","jp":"わたしは がくせいです。","romaji":"watashi wa gakusei desu.","hint":""},{"en":"What's your name?","jp":"おなまえは なんですか？","romaji":"onamae wa nan desu ka?","hint":"か makes it a question"},{"en":"My friend is a student.","jp":"ともだちは がくせいです。","romaji":"tomodachi wa gakusei desu.","hint":""}]},{"id":"greetings","section":"First Contact","title":"Greetings & Courtesies","grammar":"あいさつ — set phrases","grammarNote":"These greetings never change form — learn each as one chunk. ございます makes おはよう and ありがとう more polite.","vocab":[{"jp":"おはよう","romaji":"ohayou","en":"good morning","pos":"expr"},{"jp":"こんにちは","romaji":"konnichiwa","en":"hello / good afternoon","pos":"expr"},{"jp":"こんばんは","romaji":"konbanwa","en":"good evening","pos":"expr"},{"jp":"ありがとう","romaji":"arigatou","en":"thank you","pos":"expr"},{"jp":"ございます","romaji":"gozaimasu","en":"(makes a phrase polite)","pos":"aux"},{"jp":"すみません","romaji":"sumimasen","en":"excuse me / sorry","pos":"expr"},{"jp":"さようなら","romaji":"sayounara","en":"goodbye","pos":"expr"},{"jp":"はい","romaji":"hai","en":"yes","pos":"expr"},{"jp":"いいえ","romaji":"iie","en":"no","pos":"expr"}],"sentences":[{"en":"Good morning.","jp":"おはよう ございます。","romaji":"ohayou gozaimasu.","hint":"ございます = polite"},{"en":"Hello.","jp":"こんにちは。","romaji":"konnichiwa.","hint":""},{"en":"Good evening.","jp":"こんばんは。","romaji":"konbanwa.","hint":""},{"en":"Thank you very much.","jp":"ありがとう ございます。","romaji":"arigatou gozaimasu.","hint":""},{"en":"Excuse me. / I'm sorry.","jp":"すみません。","romaji":"sumimasen.","hint":""},{"en":"Yes, that's right.","jp":"はい、そうです。","romaji":"hai, sou desu.","hint":"そう = so / that way"},{"en":"No, that's wrong.","jp":"いいえ、ちがいます。","romaji":"iie, chigaimasu.","hint":""},{"en":"Goodbye.","jp":"さようなら。","romaji":"sayounara.","hint":""}]},{"id":"this-that","section":"First Contact","title":"This, That & “Whose”","grammar":"これ・それ・あれ  ·  の","grammarNote":"これ = this (by me), それ = that (by you), あれ = that (over there), どれ = which. の links two nouns: わたしの ほん = my book.","vocab":[{"jp":"これ","romaji":"kore","en":"this","pos":"n"},{"jp":"それ","romaji":"sore","en":"that (by you)","pos":"n"},{"jp":"あれ","romaji":"are","en":"that (over there)","pos":"n"},{"jp":"どれ","romaji":"dore","en":"which one","pos":"n"},{"jp":"ほん","romaji":"hon","en":"book","pos":"n"},{"jp":"かばん","romaji":"kaban","en":"bag","pos":"n"},{"jp":"わたしの","romaji":"watashi no","en":"my / mine","pos":"n"}],"sentences":[{"en":"What is this?","jp":"これは なんですか？","romaji":"kore wa nan desu ka?","hint":""},{"en":"This is a book.","jp":"これは ほんです。","romaji":"kore wa hon desu.","hint":""},{"en":"That (by you) is a bag.","jp":"それは かばんです。","romaji":"sore wa kaban desu.","hint":""},{"en":"That over there is my bag.","jp":"あれは わたしの かばんです。","romaji":"are wa watashi no kaban desu.","hint":"の = 's / of"},{"en":"This is my book.","jp":"これは わたしの ほんです。","romaji":"kore wa watashi no hon desu.","hint":""},{"en":"Which one is your book?","jp":"どれが あなたの ほんですか？","romaji":"dore ga anata no hon desu ka?","hint":"あなた = you"},{"en":"Is that (by you) a book?","jp":"それは ほんですか？","romaji":"sore wa hon desu ka?","hint":""}]},{"id":"numbers","section":"First Contact","title":"Numbers 1–10 & Beyond","grammar":"すうじ 1–10  ·  10+n  ·  n×10","grammarNote":"The core numbers 1–10 power everything — prices, time, counting. Past ten it's pure assembly: 11 is ten-one (じゅういち), 12 is ten-two. The tens are the same trick backwards: 20 is two-tens (にじゅう), 30 three-tens.","vocab":[{"jp":"いち","romaji":"ichi","en":"one (1)","pos":"n"},{"jp":"に","romaji":"ni","en":"two (2)","pos":"n"},{"jp":"さん","romaji":"san","en":"three (3)","pos":"n"},{"jp":"よん","romaji":"yon","en":"four (4)","pos":"n"},{"jp":"ご","romaji":"go","en":"five (5)","pos":"n"},{"jp":"ろく","romaji":"roku","en":"six (6)","pos":"n"},{"jp":"なな","romaji":"nana","en":"seven (7)","pos":"n"},{"jp":"はち","romaji":"hachi","en":"eight (8)","pos":"n"},{"jp":"きゅう","romaji":"kyuu","en":"nine (9)","pos":"n"},{"jp":"じゅう","romaji":"juu","en":"ten (10)","pos":"n"},{"jp":"じゅういち","romaji":"juuichi","en":"eleven (11)","pos":"n"},{"jp":"にじゅう","romaji":"nijuu","en":"twenty (20)","pos":"n"},{"jp":"さんじゅう","romaji":"sanjuu","en":"thirty (30)","pos":"n"}],"sentences":[{"en":"One, two, three, four, five.","jp":"いち、に、さん、よん、ご。","romaji":"ichi, ni, san, yon, go.","hint":""},{"en":"Six, seven, eight, nine, ten.","jp":"ろく、なな、はち、きゅう、じゅう。","romaji":"roku, nana, hachi, kyuu, juu.","hint":""},{"en":"Eleven, twelve, thirteen.","jp":"じゅういち、じゅうに、じゅうさん。","romaji":"juuichi, juuni, juusan.","hint":"10 + n"},{"en":"Twenty, thirty, forty.","jp":"にじゅう、さんじゅう、よんじゅう。","romaji":"nijuu, sanjuu, yonjuu.","hint":"n × 10"},{"en":"Ninety-nine!","jp":"きゅうじゅうきゅう！","romaji":"kyuujuukyuu!","hint":"9 tens and a 9"},{"en":"Ten, twenty, one hundred.","jp":"じゅう、にじゅう、ひゃく。","romaji":"juu, nijuu, hyaku.","hint":""}]},{"id":"age","section":"First Contact","title":"How Old? (〜さい)","grammar":"〜さい  ·  なんさいですか","grammarNote":"Age is a number plus さい: きゅうさい = nine years old. Ten squeezes to じゅっさい. Ask with なんさいですか. Numbers past ten stay regular — にじゅうごさい is 25. (Twenty years old has a special word — it comes later.)","vocab":[{"jp":"なんさい","romaji":"nan-sai","en":"how old","pos":"n"},{"jp":"さい","romaji":"sai","en":"years old (counter)","pos":"n"},{"jp":"こども","romaji":"kodomo","en":"child","pos":"n"},{"jp":"おとな","romaji":"otona","en":"adult","pos":"n"},{"jp":"わかい","romaji":"wakai","en":"young","pos":"adj"},{"jp":"とし","romaji":"toshi","en":"age / years","pos":"n"}],"sentences":[{"en":"How old are you?","jp":"なんさいですか？","romaji":"nan-sai desu ka?","hint":""},{"en":"I'm ten years old.","jp":"じゅっさいです。","romaji":"jussai desu.","hint":"10 + さい → じゅっさい"},{"en":"My friend is nine years old.","jp":"ともだちは きゅうさいです。","romaji":"tomodachi wa kyuu-sai desu.","hint":"〜さい = years old"},{"en":"How old is your friend?","jp":"ともだちは なんさいですか？","romaji":"tomodachi wa nan-sai desu ka?","hint":""},{"en":"I'm twenty-five years old.","jp":"にじゅうごさいです。","romaji":"nijuu-go-sai desu.","hint":"past ten it stays regular"},{"en":"The child is five years old.","jp":"こどもは ごさいです。","romaji":"kodomo wa go-sai desu.","hint":""}]},{"id":"shop","section":"Getting Things","title":"At a Shop — Ordering & Prices","grammar":"〜を ください  ·  〜は いくらですか","grammarNote":"を marks the thing you want; add ください to politely ask for it. To ask a price: [thing] は いくらですか？","vocab":[{"jp":"これ","romaji":"kore","en":"this","pos":"n"},{"jp":"いくら","romaji":"ikura","en":"how much","pos":"n"},{"jp":"みず","romaji":"mizu","en":"water","pos":"n"},{"jp":"コーヒー","romaji":"koohii","en":"coffee","pos":"n"},{"jp":"ひとつ","romaji":"hitotsu","en":"one (item)","pos":"n"},{"jp":"ください","romaji":"kudasai","en":"please give me","pos":"aux"}],"sentences":[{"en":"How much is this?","jp":"これは いくらですか？","romaji":"kore wa ikura desu ka?","hint":""},{"en":"Water, please.","jp":"みずを ください。","romaji":"mizu o kudasai.","hint":"を marks what you want"},{"en":"Coffee, please.","jp":"コーヒーを ください。","romaji":"koohii o kudasai.","hint":""},{"en":"One coffee, please.","jp":"コーヒーを ひとつ ください。","romaji":"koohii o hitotsu kudasai.","hint":""},{"en":"This one, please.","jp":"これを ください。","romaji":"kore o kudasai.","hint":""},{"en":"How much is the water?","jp":"みずは いくらですか？","romaji":"mizu wa ikura desu ka?","hint":""}]},{"id":"money","section":"Getting Things","title":"Money & Prices","grammar":"ひゃく・せん  ·  〜えん  ·  いくら","grammarNote":"Bigger numbers: ひゃく = 100, せん = 1000. Prices take 〜えん (yen). Watch the sound-shift: 300 is さんびゃく, not さんひゃく.","vocab":[{"jp":"ひゃく","romaji":"hyaku","en":"hundred (100)","pos":"n"},{"jp":"せん","romaji":"sen","en":"thousand (1000)","pos":"n"},{"jp":"えん","romaji":"en","en":"yen (¥)","pos":"n"},{"jp":"ごひゃく","romaji":"gohyaku","en":"500","pos":"n"},{"jp":"さんびゃく","romaji":"sanbyaku","en":"300","pos":"n"},{"jp":"いくら","romaji":"ikura","en":"how much","pos":"n"},{"jp":"たかい","romaji":"takai","en":"expensive","pos":"adj"},{"jp":"やすい","romaji":"yasui","en":"cheap","pos":"adj"}],"sentences":[{"en":"How much is this?","jp":"これは いくらですか？","romaji":"kore wa ikura desu ka?","hint":""},{"en":"It's 100 yen.","jp":"ひゃくえんです。","romaji":"hyaku-en desu.","hint":""},{"en":"It's 500 yen.","jp":"ごひゃくえんです。","romaji":"gohyaku-en desu.","hint":""},{"en":"The coffee is 300 yen.","jp":"コーヒーは さんびゃくえんです。","romaji":"koohii wa sanbyaku-en desu.","hint":"300 = さんびゃく (sound shift)"},{"en":"Is it expensive?","jp":"たかいですか？","romaji":"takai desu ka?","hint":""},{"en":"No, it's cheap.","jp":"いいえ、やすいです。","romaji":"iie, yasui desu.","hint":""},{"en":"The water is 100 yen.","jp":"みずは ひゃくえんです。","romaji":"mizu wa hyaku-en desu.","hint":""},{"en":"This one is 1000 yen.","jp":"これは せんえんです。","romaji":"kore wa sen-en desu.","hint":""}]},{"id":"counters","section":"Getting Things","title":"Counting Things (ひとつ…)","grammar":"ひとつ〜とお  ·  〜を [かず] ください","grammarNote":"Japanese has more than one counting system, but this native one is the everyday all-purpose counter — learn it first: ひとつ(1), ふたつ(2), みっつ(3), よっつ(4), いつつ(5), むっつ(6), ななつ(7), やっつ(8), ここのつ(9), とお(10). Order things with [thing]を [number] ください.","vocab":[{"jp":"ひとつ","romaji":"hitotsu","en":"one (item)","pos":"n"},{"jp":"ふたつ","romaji":"futatsu","en":"two (items)","pos":"n"},{"jp":"みっつ","romaji":"mittsu","en":"three (items)","pos":"n"},{"jp":"よっつ","romaji":"yottsu","en":"four (items)","pos":"n"},{"jp":"いつつ","romaji":"itsutsu","en":"five (items)","pos":"n"},{"jp":"むっつ","romaji":"muttsu","en":"six (items)","pos":"n"},{"jp":"ななつ","romaji":"nanatsu","en":"seven (items)","pos":"n"},{"jp":"やっつ","romaji":"yattsu","en":"eight (items)","pos":"n"},{"jp":"ここのつ","romaji":"kokonotsu","en":"nine (items)","pos":"n"},{"jp":"とお","romaji":"too","en":"ten (items)","pos":"n"},{"jp":"いくつ","romaji":"ikutsu","en":"how many","pos":"n"},{"jp":"ぜんぶ","romaji":"zenbu","en":"all of it","pos":"n"}],"sentences":[{"en":"One, please.","jp":"ひとつ ください。","romaji":"hitotsu kudasai.","hint":""},{"en":"Two coffees, please.","jp":"コーヒーを ふたつ ください。","romaji":"koohii o futatsu kudasai.","hint":""},{"en":"Three waters, please.","jp":"みずを みっつ ください。","romaji":"mizu o mittsu kudasai.","hint":""},{"en":"How many?","jp":"いくつですか？","romaji":"ikutsu desu ka?","hint":"いくつ = how many"},{"en":"Five, please.","jp":"いつつ ください。","romaji":"itsutsu kudasai.","hint":""},{"en":"All of it, please.","jp":"ぜんぶ ください。","romaji":"zenbu kudasai.","hint":""},{"en":"Four, please.","jp":"よっつ ください。","romaji":"yottsu kudasai.","hint":""}]},{"id":"where","section":"Getting Things","title":"Where Is It? (ここ・どこ)","grammar":"ここ・そこ・あそこ・どこ  ·  〜に あります／います","grammarNote":"ここ=here, そこ=there (by you), あそこ=over there, どこ=where. あります = there is (things); います = there is (people/animals). The place takes に.","vocab":[{"jp":"ここ","romaji":"koko","en":"here","pos":"n"},{"jp":"そこ","romaji":"soko","en":"there (by you)","pos":"n"},{"jp":"あそこ","romaji":"asoko","en":"over there","pos":"n"},{"jp":"どこ","romaji":"doko","en":"where","pos":"n"},{"jp":"トイレ","romaji":"toire","en":"toilet / restroom","pos":"n"},{"jp":"えき","romaji":"eki","en":"station","pos":"n"},{"jp":"あります","romaji":"arimasu","en":"there is (a thing)","pos":"v"},{"jp":"います","romaji":"imasu","en":"there is (a person)","pos":"v"}],"sentences":[{"en":"Where is the restroom?","jp":"トイレは どこですか？","romaji":"toire wa doko desu ka?","hint":"the most useful sentence!"},{"en":"It's over there.","jp":"あそこです。","romaji":"asoko desu.","hint":""},{"en":"The station is here.","jp":"えきは ここです。","romaji":"eki wa koko desu.","hint":""},{"en":"Is there (any) water?","jp":"みずは ありますか？","romaji":"mizu wa arimasu ka?","hint":""},{"en":"Yes, it's here.","jp":"はい、ここに あります。","romaji":"hai, koko ni arimasu.","hint":"に marks the place"},{"en":"My friend is over there.","jp":"ともだちは あそこに います。","romaji":"tomodachi wa asoko ni imasu.","hint":"います for people"},{"en":"Where is the station?","jp":"えきは どこですか？","romaji":"eki wa doko desu ka?","hint":""}]},{"id":"cafe","section":"Getting Things","title":"At the Café (Putting It Together)","grammar":"review  ·  〜と〜  ·  おねがいします","grammarNote":"Combine ordering, counting and prices. と joins nouns (A と B = A and B); おねがいします is a polite “please” for requests.","vocab":[{"jp":"おちゃ","romaji":"ocha","en":"(green) tea","pos":"n"},{"jp":"ケーキ","romaji":"keeki","en":"cake","pos":"n"},{"jp":"メニュー","romaji":"menyuu","en":"menu","pos":"n"},{"jp":"おねがいします","romaji":"onegai-shimasu","en":"please (request)","pos":"expr"},{"jp":"コーヒー","romaji":"koohii","en":"coffee","pos":"n"},{"jp":"みず","romaji":"mizu","en":"water","pos":"n"}],"sentences":[{"en":"The menu, please.","jp":"メニューを おねがいします。","romaji":"menyuu o onegai-shimasu.","hint":"おねがいします = polite please"},{"en":"A coffee and a tea, please.","jp":"コーヒーと おちゃを ください。","romaji":"koohii to ocha o kudasai.","hint":"と = and"},{"en":"How much is the cake?","jp":"ケーキは いくらですか？","romaji":"keeki wa ikura desu ka?","hint":""},{"en":"Two teas, please.","jp":"おちゃを ふたつ ください。","romaji":"ocha o futatsu kudasai.","hint":""},{"en":"Water, please.","jp":"みずを おねがいします。","romaji":"mizu o onegai-shimasu.","hint":""},{"en":"Thank you very much.","jp":"ありがとう ございます。","romaji":"arigatou gozaimasu.","hint":""}]},{"id":"verbs","section":"Doing Things","title":"Doing Things (〜ます)","grammar":"polite present 〜ます","grammarNote":"〜ます is the polite present — it covers what you do, habits, and the near future (“I do / I'll do”). Each verb has its own ます-form; learn these core ones first.","vocab":[{"jp":"たべます","romaji":"tabemasu","en":"eat  (食べる)","pos":"v"},{"jp":"のみます","romaji":"nomimasu","en":"drink  (飲む)","pos":"v"},{"jp":"みます","romaji":"mimasu","en":"see / watch  (見る)","pos":"v"},{"jp":"いきます","romaji":"ikimasu","en":"go  (行く)","pos":"v"},{"jp":"します","romaji":"shimasu","en":"do  (する)","pos":"v"},{"jp":"わかります","romaji":"wakarimasu","en":"understand  (分かる)","pos":"v"}],"sentences":[{"en":"I'll eat.","jp":"たべます。","romaji":"tabemasu.","hint":""},{"en":"I'll drink.","jp":"のみます。","romaji":"nomimasu.","hint":""},{"en":"I'll watch.","jp":"みます。","romaji":"mimasu.","hint":""},{"en":"I'm going.","jp":"いきます。","romaji":"ikimasu.","hint":""},{"en":"I'll do it.","jp":"します。","romaji":"shimasu.","hint":""},{"en":"I understand.","jp":"わかります。","romaji":"wakarimasu.","hint":"also: “I get it”"}]},{"id":"object","section":"Doing Things","title":"What You Do It To (を)","grammar":"〜を 〜ます  (object + verb)","grammarNote":"を marks the direct object — the thing the verb acts on: [thing]を [verb]ます. The object comes before the verb.","vocab":[{"jp":"ごはん","romaji":"gohan","en":"rice / meal","pos":"n"},{"jp":"ほん","romaji":"hon","en":"book","pos":"n"},{"jp":"えいが","romaji":"eiga","en":"movie","pos":"n"},{"jp":"にほんご","romaji":"nihongo","en":"Japanese (language)","pos":"n"},{"jp":"よみます","romaji":"yomimasu","en":"read  (読む)","pos":"v"},{"jp":"みず","romaji":"mizu","en":"water","pos":"n"}],"sentences":[{"en":"I eat a meal.","jp":"ごはんを たべます。","romaji":"gohan o tabemasu.","hint":""},{"en":"I drink water.","jp":"みずを のみます。","romaji":"mizu o nomimasu.","hint":""},{"en":"I watch a movie.","jp":"えいがを みます。","romaji":"eiga o mimasu.","hint":""},{"en":"I read a book.","jp":"ほんを よみます。","romaji":"hon o yomimasu.","hint":""},{"en":"I read Japanese.","jp":"にほんごを よみます。","romaji":"nihongo o yomimasu.","hint":""},{"en":"I drink coffee.","jp":"コーヒーを のみます。","romaji":"koohii o nomimasu.","hint":""}]},{"id":"negative","section":"Doing Things","title":"Saying No & Asking (〜ません／〜ますか)","grammar":"〜ません (don't)  ·  〜ますか (do you…?)","grammarNote":"Make a verb negative by swapping ます for ません. Turn any statement into a yes/no question by adding か on the end: 〜ますか.","vocab":[{"jp":"にく","romaji":"niku","en":"meat","pos":"n"},{"jp":"おさけ","romaji":"osake","en":"alcohol / sake","pos":"n"},{"jp":"まいにち","romaji":"mainichi","en":"every day","pos":"n"},{"jp":"のみません","romaji":"nomimasen","en":"don't drink","pos":"v"},{"jp":"たべません","romaji":"tabemasen","en":"don't eat","pos":"v"},{"jp":"わかりません","romaji":"wakarimasen","en":"don't understand","pos":"v"}],"sentences":[{"en":"Do you drink sake?","jp":"おさけを のみますか？","romaji":"osake o nomimasu ka?","hint":""},{"en":"No, I don't drink.","jp":"いいえ、のみません。","romaji":"iie, nomimasen.","hint":""},{"en":"I don't eat meat.","jp":"にくを たべません。","romaji":"niku o tabemasen.","hint":"handy at restaurants"},{"en":"Do you go every day?","jp":"まいにち いきますか？","romaji":"mainichi ikimasu ka?","hint":""},{"en":"Yes, I go.","jp":"はい、いきます。","romaji":"hai, ikimasu.","hint":""},{"en":"I don't understand.","jp":"わかりません。","romaji":"wakarimasen.","hint":"super useful!"}]},{"id":"coming-going","section":"Doing Things","title":"Coming & Going (〜に いきます)","grammar":"[place]に いきます／きます／かえります","grammarNote":"Movement verbs take a destination marked with に: [place]に いきます = go to [place]. きます = come; かえります = return / go home.","vocab":[{"jp":"がっこう","romaji":"gakkou","en":"school","pos":"n"},{"jp":"うち","romaji":"uchi","en":"home / house","pos":"n"},{"jp":"きます","romaji":"kimasu","en":"come  (来る)","pos":"v"},{"jp":"かえります","romaji":"kaerimasu","en":"return / go home  (帰る)","pos":"v"},{"jp":"あした","romaji":"ashita","en":"tomorrow","pos":"n"},{"jp":"にほん","romaji":"nihon","en":"Japan","pos":"n"}],"sentences":[{"en":"I go to school.","jp":"がっこうに いきます。","romaji":"gakkou ni ikimasu.","hint":""},{"en":"I'm going home.","jp":"うちに かえります。","romaji":"uchi ni kaerimasu.","hint":""},{"en":"Will you come tomorrow?","jp":"あした きますか？","romaji":"ashita kimasu ka?","hint":""},{"en":"Yes, I'll come.","jp":"はい、きます。","romaji":"hai, kimasu.","hint":""},{"en":"I'm going to Japan.","jp":"にほんに いきます。","romaji":"nihon ni ikimasu.","hint":""},{"en":"I'll go home tomorrow.","jp":"あした うちに かえります。","romaji":"ashita uchi ni kaerimasu.","hint":""}]},{"id":"routine","section":"Daily Life","title":"My Daily Routine","grammar":"present 〜ます  ·  time に  ·  で (by)","grammarNote":"〜ます is the polite present — also used for habits and the near future. Put に after a clock time, and で after a means of transport.","vocab":[{"jp":"まいあさ","romaji":"maiasa","en":"every morning","pos":"n"},{"jp":"しちじ","romaji":"shichi-ji","en":"7 o'clock","pos":"n"},{"jp":"でんしゃ","romaji":"densha","en":"train","pos":"n"},{"jp":"しごと","romaji":"shigoto","en":"work","pos":"n"},{"jp":"コーヒー","romaji":"koohii","en":"coffee","pos":"n"},{"jp":"おきます","romaji":"okimasu","en":"wake up  (起きる)","pos":"v"},{"jp":"のみます","romaji":"nomimasu","en":"drink  (飲む)","pos":"v"},{"jp":"いきます","romaji":"ikimasu","en":"go  (行く)","pos":"v"}],"sentences":[{"en":"I wake up at seven.","jp":"しちじに おきます。","romaji":"shichi-ji ni okimasu.","hint":"に after a clock time"},{"en":"I drink coffee every morning.","jp":"まいあさ コーヒーを のみます。","romaji":"maiasa koohii o nomimasu.","hint":""},{"en":"I go to work by train.","jp":"でんしゃで しごとに いきます。","romaji":"densha de shigoto ni ikimasu.","hint":"で = by means of"},{"en":"I go to work at seven.","jp":"しちじに しごとに いきます。","romaji":"shichi-ji ni shigoto ni ikimasu.","hint":""},{"en":"Every morning I go by train.","jp":"まいあさ でんしゃで いきます。","romaji":"maiasa densha de ikimasu.","hint":""},{"en":"I drink coffee.","jp":"コーヒーを のみます。","romaji":"koohii o nomimasu.","hint":""}]},{"id":"telling-time","section":"Daily Life","title":"Telling Time (なんじ)","grammar":"いま なんじ  ·  〜じ・はん  ·  ごぜん／ごご","grammarNote":"Ask the time with いま なんじですか. Hours take 〜じ; はん = half past. ごぜん = AM, ごご = PM. Pin an action to a time with に.","vocab":[{"jp":"いま","romaji":"ima","en":"now","pos":"n"},{"jp":"なんじ","romaji":"nan-ji","en":"what time","pos":"n"},{"jp":"はん","romaji":"han","en":"half (past)","pos":"n"},{"jp":"ごぜん","romaji":"gozen","en":"AM","pos":"n"},{"jp":"ごご","romaji":"gogo","en":"PM","pos":"n"},{"jp":"ねます","romaji":"nemasu","en":"sleep / go to bed  (寝る)","pos":"v"}],"sentences":[{"en":"What time is it now?","jp":"いま なんじですか？","romaji":"ima nan-ji desu ka?","hint":""},{"en":"It's 7 o'clock.","jp":"しちじです。","romaji":"shichi-ji desu.","hint":""},{"en":"It's half past 8.","jp":"はちじはんです。","romaji":"hachi-ji han desu.","hint":"はん = half past"},{"en":"I go to bed at 11.","jp":"じゅういちじに ねます。","romaji":"juuichi-ji ni nemasu.","hint":""},{"en":"I wake up at 6 AM.","jp":"ごぜん ろくじに おきます。","romaji":"gozen roku-ji ni okimasu.","hint":""},{"en":"Work is at 9.","jp":"しごとは くじです。","romaji":"shigoto wa ku-ji desu.","hint":""},{"en":"I sleep at 11 PM.","jp":"ごご じゅういちじに ねます。","romaji":"gogo jūichi-ji ni nemasu.","hint":""}]},{"id":"frequency","section":"Daily Life","title":"How Often (よく・ときどき)","grammar":"よく・ときどき  ·  あまり／ぜんぜん 〜ません","grammarNote":"Frequency words sit before the verb: よく = often, ときどき = sometimes. あまり and ぜんぜん pair with a negative verb — あまり〜ません = not much, ぜんぜん〜ません = not at all.","vocab":[{"jp":"よく","romaji":"yoku","en":"often","pos":"adv"},{"jp":"ときどき","romaji":"tokidoki","en":"sometimes","pos":"adv"},{"jp":"あまり","romaji":"amari","en":"not much (+ neg)","pos":"adv"},{"jp":"ぜんぜん","romaji":"zenzen","en":"not at all (+ neg)","pos":"adv"},{"jp":"テレビ","romaji":"terebi","en":"TV","pos":"n"},{"jp":"べんきょうします","romaji":"benkyou-shimasu","en":"study  (勉強する)","pos":"v"}],"sentences":[{"en":"I often watch TV.","jp":"よく テレビを みます。","romaji":"yoku terebi o mimasu.","hint":""},{"en":"I sometimes drink coffee.","jp":"ときどき コーヒーを のみます。","romaji":"tokidoki koohii o nomimasu.","hint":""},{"en":"I don't watch much.","jp":"あまり みません。","romaji":"amari mimasen.","hint":"あまり needs a negative verb"},{"en":"I don't drink at all.","jp":"ぜんぜん のみません。","romaji":"zenzen nomimasen.","hint":""},{"en":"Do you go often?","jp":"よく いきますか？","romaji":"yoku ikimasu ka?","hint":""},{"en":"I study every day.","jp":"まいにち べんきょうします。","romaji":"mainichi benkyou-shimasu.","hint":""}]},{"id":"activities","section":"Daily Life","title":"Where You Do It (〜で)","grammar":"[place]で [verb]  ·  あさ／よる","grammarNote":"で also marks WHERE an action happens: [place]で [verb]. (Same particle as “by train” — both uses share で.) あさ = morning, よる = night.","vocab":[{"jp":"かいしゃ","romaji":"kaisha","en":"company / office","pos":"n"},{"jp":"はたらきます","romaji":"hatarakimasu","en":"work  (働く)","pos":"v"},{"jp":"あさ","romaji":"asa","en":"morning","pos":"n"},{"jp":"よる","romaji":"yoru","en":"night / evening","pos":"n"},{"jp":"うち","romaji":"uchi","en":"home / house","pos":"n"},{"jp":"なに","romaji":"nani","en":"what","pos":"n"}],"sentences":[{"en":"I work at a company.","jp":"かいしゃで はたらきます。","romaji":"kaisha de hatarakimasu.","hint":"で = at (where the action happens)"},{"en":"I study at home.","jp":"うちで べんきょうします。","romaji":"uchi de benkyou-shimasu.","hint":""},{"en":"I eat in the morning.","jp":"あさ ごはんを たべます。","romaji":"asa gohan o tabemasu.","hint":""},{"en":"I watch TV at night.","jp":"よる テレビを みます。","romaji":"yoru terebi o mimasu.","hint":""},{"en":"I sleep at home.","jp":"うちで ねます。","romaji":"uchi de nemasu.","hint":""},{"en":"What do you do at the office?","jp":"かいしゃで なにを しますか？","romaji":"kaisha de nani o shimasu ka?","hint":""}]},{"id":"past-1","section":"The Past","title":"What Did You Do Yesterday?","grammar":"past 〜ました  ·  を / に / と","grammarNote":"For the past, the polite ending becomes 〜ました. Mark the thing you act on with を, the person you meet with に, and “together with” someone with と.","vocab":[{"jp":"きのう","romaji":"kinou","en":"yesterday","pos":"n"},{"jp":"ともだち","romaji":"tomodachi","en":"friend","pos":"n"},{"jp":"えいが","romaji":"eiga","en":"movie","pos":"n"},{"jp":"ごはん","romaji":"gohan","en":"meal / food","pos":"n"},{"jp":"なに","romaji":"nani","en":"what","pos":"n"},{"jp":"だれ","romaji":"dare","en":"who","pos":"n"},{"jp":"みました","romaji":"mimashita","en":"watched / saw  (見る)","pos":"v"},{"jp":"あいました","romaji":"aimashita","en":"met  (会う)","pos":"v"},{"jp":"たべました","romaji":"tabemashita","en":"ate  (食べる)","pos":"v"}],"sentences":[{"en":"Yesterday I watched a movie.","jp":"きのう えいがを みました。","romaji":"kinou eiga o mimashita.","hint":"を marks the thing you watched"},{"en":"Yesterday I met a friend.","jp":"きのう ともだちに あいました。","romaji":"kinou tomodachi ni aimashita.","hint":"あう takes に for the person"},{"en":"Yesterday I ate a meal.","jp":"きのう ごはんを たべました。","romaji":"kinou gohan o tabemashita.","hint":""},{"en":"I watched a movie with a friend.","jp":"ともだちと えいがを みました。","romaji":"tomodachi to eiga o mimashita.","hint":"と = (together) with"},{"en":"I ate a meal with a friend.","jp":"ともだちと ごはんを たべました。","romaji":"tomodachi to gohan o tabemashita.","hint":""},{"en":"What did you watch yesterday?","jp":"きのう なにを みましたか？","romaji":"kinou nani o mimashita ka?","hint":"なに = what"},{"en":"Who did you meet yesterday?","jp":"きのう だれに あいましたか？","romaji":"kinou dare ni aimashita ka?","hint":"だれ = who"},{"en":"Yesterday I watched a movie with a friend.","jp":"きのう ともだちと えいがを みました。","romaji":"kinou tomodachi to eiga o mimashita.","hint":"putting it all together"}]},{"id":"past-negative","section":"The Past","title":"Didn't Do It (〜ませんでした)","grammar":"〜ませんでした (didn't)  ·  なにも + neg","grammarNote":"The past negative is 〜ませんでした (“didn't”). Add か for a past question: 〜ましたか. なにも + a negative verb = “nothing”.","vocab":[{"jp":"せんしゅう","romaji":"senshuu","en":"last week","pos":"n"},{"jp":"なにも","romaji":"nani mo","en":"nothing (+ neg)","pos":"n"},{"jp":"かいました","romaji":"kaimashita","en":"bought  (買う)","pos":"v"},{"jp":"いきませんでした","romaji":"ikimasen deshita","en":"didn't go","pos":"v"},{"jp":"しました","romaji":"shimashita","en":"did  (する)","pos":"v"},{"jp":"ほん","romaji":"hon","en":"book","pos":"n"}],"sentences":[{"en":"Did you go yesterday?","jp":"きのう いきましたか？","romaji":"kinou ikimashita ka?","hint":""},{"en":"No, I didn't go.","jp":"いいえ、いきませんでした。","romaji":"iie, ikimasen deshita.","hint":""},{"en":"I didn't eat anything.","jp":"なにも たべませんでした。","romaji":"nani mo tabemasen deshita.","hint":"なにも + negative = nothing"},{"en":"What did you do last week?","jp":"せんしゅう なにを しましたか？","romaji":"senshuu nani o shimashita ka?","hint":""},{"en":"I bought a book.","jp":"ほんを かいました。","romaji":"hon o kaimashita.","hint":""},{"en":"I didn't do anything.","jp":"なにも しませんでした。","romaji":"nani mo shimasen deshita.","hint":""}]},{"id":"was-were","section":"The Past","title":"It Was… (でした)","grammar":"でした (was/were)  ·  〜じゃ ありませんでした","grammarNote":"The past of です is でした (“was / were”). For “wasn't,” use 〜じゃ ありませんでした. These work with nouns, not verbs.","vocab":[{"jp":"でした","romaji":"deshita","en":"was / were","pos":"cop"},{"jp":"やすみ","romaji":"yasumi","en":"day off / holiday","pos":"n"},{"jp":"せんせい","romaji":"sensei","en":"teacher","pos":"n"},{"jp":"じゃ ありませんでした","romaji":"ja arimasen deshita","en":"was not","pos":"cop"},{"jp":"おすし","romaji":"osushi","en":"sushi","pos":"n"},{"jp":"きのう","romaji":"kinou","en":"yesterday","pos":"n"}],"sentences":[{"en":"Yesterday was a day off.","jp":"きのうは やすみでした。","romaji":"kinou wa yasumi deshita.","hint":""},{"en":"It was sushi.","jp":"おすしでした。","romaji":"osushi deshita.","hint":""},{"en":"It was 500 yen.","jp":"ごひゃくえんでした。","romaji":"gohyaku-en deshita.","hint":""},{"en":"It wasn't water.","jp":"みずじゃ ありませんでした。","romaji":"mizu ja arimasen deshita.","hint":"じゃ ありませんでした = wasn't"},{"en":"Was it coffee?","jp":"コーヒーでしたか？","romaji":"koohii deshita ka?","hint":""},{"en":"(She) was a teacher.","jp":"せんせいでした。","romaji":"sensei deshita.","hint":""}]},{"id":"sequence","section":"The Past","title":"And Then… (それから)","grammar":"それから (and then)  ·  chaining 〜ました","grammarNote":"Tell a story in order with それから (“after that / then”). Each step stays a full 〜ました sentence — no fancy conjugation needed yet.","vocab":[{"jp":"それから","romaji":"sorekara","en":"and then","pos":"conj"},{"jp":"あさごはん","romaji":"asa-gohan","en":"breakfast","pos":"n"},{"jp":"ばんごはん","romaji":"ban-gohan","en":"dinner","pos":"n"},{"jp":"こうえん","romaji":"kouen","en":"park","pos":"n"},{"jp":"かえりました","romaji":"kaerimashita","en":"went home  (帰る)","pos":"v"},{"jp":"ねました","romaji":"nemashita","en":"went to bed  (寝る)","pos":"v"}],"sentences":[{"en":"I woke up at 7.","jp":"しちじに おきました。","romaji":"shichi-ji ni okimashita.","hint":""},{"en":"And then I ate breakfast.","jp":"それから あさごはんを たべました。","romaji":"sorekara asa-gohan o tabemashita.","hint":"それから = and then"},{"en":"I went to the park.","jp":"こうえんに いきました。","romaji":"kouen ni ikimashita.","hint":""},{"en":"And then I went home.","jp":"それから うちに かえりました。","romaji":"sorekara uchi ni kaerimashita.","hint":""},{"en":"I ate dinner.","jp":"ばんごはんを たべました。","romaji":"ban-gohan o tabemashita.","hint":""},{"en":"And then I went to bed.","jp":"それから ねました。","romaji":"sorekara nemashita.","hint":""}]},{"id":"wants","section":"Wants & Plans","title":"What I Want to Do","grammar":"〜たい (want to)  ·  〜が ほしい (want a thing)","grammarNote":"Verb-stem + たい says you want to DO something (のむ → のみたい). For wanting a THING (a noun), use [thing] が ほしい.","vocab":[{"jp":"にほん","romaji":"nihon","en":"Japan","pos":"n"},{"jp":"おすし","romaji":"osushi","en":"sushi","pos":"n"},{"jp":"くるま","romaji":"kuruma","en":"car","pos":"n"},{"jp":"いきたい","romaji":"ikitai","en":"want to go","pos":"v"},{"jp":"たべたい","romaji":"tabetai","en":"want to eat","pos":"v"},{"jp":"やすみたい","romaji":"yasumitai","en":"want to rest","pos":"v"},{"jp":"ほしい","romaji":"hoshii","en":"want (a thing)","pos":"adj"}],"sentences":[{"en":"I want to go to Japan.","jp":"にほんに いきたいです。","romaji":"nihon ni ikitai desu.","hint":"に marks the destination"},{"en":"I want to eat sushi.","jp":"おすしが たべたいです。","romaji":"osushi ga tabetai desu.","hint":""},{"en":"I want to rest.","jp":"やすみたいです。","romaji":"yasumitai desu.","hint":""},{"en":"I want a car.","jp":"くるまが ほしいです。","romaji":"kuruma ga hoshii desu.","hint":"が ほしい = want a thing"},{"en":"I want to eat sushi in Japan.","jp":"にほんで おすしが たべたいです。","romaji":"nihon de osushi ga tabetai desu.","hint":"で = at/in (where it happens)"},{"en":"I want to go by car.","jp":"くるまで いきたいです。","romaji":"kuruma de ikitai desu.","hint":""}]},{"id":"lets","section":"Wants & Plans","title":"Let's… (〜ましょう／〜ませんか)","grammar":"〜ましょう (let's)  ·  〜ませんか (shall we?)","grammarNote":"Suggest doing something together: verb-stem + ましょう = “let's…”. Invite someone politely with 〜ませんか (“won't you…? / shall we…?”). いっしょに = together.","vocab":[{"jp":"いきましょう","romaji":"ikimashou","en":"let's go","pos":"v"},{"jp":"たべましょう","romaji":"tabemashou","en":"let's eat","pos":"v"},{"jp":"しましょう","romaji":"shimashou","en":"let's do (it)","pos":"v"},{"jp":"のみませんか","romaji":"nomimasen ka","en":"won't you drink?","pos":"v"},{"jp":"みませんか","romaji":"mimasen ka","en":"won't you watch?","pos":"v"},{"jp":"いっしょに","romaji":"isshoni","en":"together","pos":"adv"}],"sentences":[{"en":"Let's go!","jp":"いきましょう！","romaji":"ikimashou!","hint":""},{"en":"Let's eat together.","jp":"いっしょに たべましょう。","romaji":"isshoni tabemashou.","hint":"いっしょに = together"},{"en":"Shall we drink coffee?","jp":"コーヒーを のみませんか？","romaji":"koohii o nomimasen ka?","hint":""},{"en":"Won't you watch a movie (with me)?","jp":"えいがを みませんか？","romaji":"eiga o mimasen ka?","hint":""},{"en":"Let's do it!","jp":"しましょう！","romaji":"shimashou!","hint":""},{"en":"Let's go to Japan.","jp":"にほんに いきましょう。","romaji":"nihon ni ikimashou.","hint":""}]},{"id":"likes","section":"Wants & Plans","title":"Likes & Dislikes (すき／きらい)","grammar":"〜が すき／きらい (です)  ·  だいすき","grammarNote":"Mark what you like with が: [thing]が すきです. For dislikes use きらいです, and for “love it” だいすきです. (すき and きらい act like な-adjectives.)","vocab":[{"jp":"すき","romaji":"suki","en":"like / fond of","pos":"adj"},{"jp":"きらい","romaji":"kirai","en":"dislike","pos":"adj"},{"jp":"だいすき","romaji":"daisuki","en":"love / really like","pos":"adj"},{"jp":"やさい","romaji":"yasai","en":"vegetables","pos":"n"},{"jp":"ねこ","romaji":"neko","en":"cat","pos":"n"},{"jp":"おんがく","romaji":"ongaku","en":"music","pos":"n"}],"sentences":[{"en":"I like sushi.","jp":"おすしが すきです。","romaji":"osushi ga suki desu.","hint":""},{"en":"I really like cats.","jp":"ねこが だいすきです。","romaji":"neko ga daisuki desu.","hint":"だいすき = love it"},{"en":"I don't like vegetables.","jp":"やさいが きらいです。","romaji":"yasai ga kirai desu.","hint":""},{"en":"Do you like coffee?","jp":"コーヒーが すきですか？","romaji":"koohii ga suki desu ka?","hint":""},{"en":"I like music.","jp":"おんがくが すきです。","romaji":"ongaku ga suki desu.","hint":""},{"en":"I really like Japan.","jp":"にほんが だいすきです。","romaji":"nihon ga daisuki desu.","hint":""}]},{"id":"can-do","section":"Wants & Plans","title":"Can Do (できます)","grammar":"〜が できます (can)  ·  すこし／じょうず","grammarNote":"できます = “can do / be able to”. For an activity-noun, use [noun]が できます: にほんごが できます = “I can (speak) Japanese”. すこし = a little; じょうず = good at.","vocab":[{"jp":"できます","romaji":"dekimasu","en":"can do  (出来る)","pos":"v"},{"jp":"えいご","romaji":"eigo","en":"English","pos":"n"},{"jp":"りょうり","romaji":"ryouri","en":"cooking","pos":"n"},{"jp":"うんてん","romaji":"unten","en":"driving","pos":"n"},{"jp":"すこし","romaji":"sukoshi","en":"a little","pos":"adv"},{"jp":"じょうず","romaji":"jouzu","en":"good at / skilled","pos":"adj"}],"sentences":[{"en":"I can (speak) Japanese.","jp":"にほんごが できます。","romaji":"nihongo ga dekimasu.","hint":""},{"en":"I can speak a little English.","jp":"えいごが すこし できます。","romaji":"eigo ga sukoshi dekimasu.","hint":"すこし = a little"},{"en":"Can you cook?","jp":"りょうりが できますか？","romaji":"ryouri ga dekimasu ka?","hint":""},{"en":"I can't drive.","jp":"うんてんが できません。","romaji":"unten ga dekimasen.","hint":""},{"en":"You're good at Japanese, aren't you!","jp":"にほんごが じょうずですね。","romaji":"nihongo ga jouzu desu ne.","hint":"ね = …right? / isn't it"},{"en":"I can do it.","jp":"できます。","romaji":"dekimasu.","hint":""}]},{"id":"adjectives","section":"Describing Things","title":"Describing Things (い-adjectives)","grammar":"い-adjectives  ·  past 〜かった","grammarNote":"い-adjectives end in 〜い (たかい = expensive). For the past, drop the い and add 〜かった (たかかった = was expensive). とても = very.","vocab":[{"jp":"えいが","romaji":"eiga","en":"movie","pos":"n"},{"jp":"りょこう","romaji":"ryokou","en":"trip","pos":"n"},{"jp":"とても","romaji":"totemo","en":"very","pos":"adv"},{"jp":"たかい","romaji":"takai","en":"expensive / high","pos":"adj"},{"jp":"おいしい","romaji":"oishii","en":"delicious","pos":"adj"},{"jp":"たのしい","romaji":"tanoshii","en":"fun / enjoyable","pos":"adj"}],"sentences":[{"en":"It's very delicious.","jp":"とても おいしいです。","romaji":"totemo oishii desu.","hint":"とても = very"},{"en":"The movie is fun.","jp":"えいがは たのしいです。","romaji":"eiga wa tanoshii desu.","hint":""},{"en":"The trip was fun.","jp":"りょこうは たのしかったです。","romaji":"ryokou wa tanoshikatta desu.","hint":"past: い → かった"},{"en":"The movie was expensive.","jp":"えいがは たかかったです。","romaji":"eiga wa takakatta desu.","hint":""},{"en":"It was very delicious.","jp":"とても おいしかったです。","romaji":"totemo oishikatta desu.","hint":""},{"en":"The trip was very fun.","jp":"りょこうは とても たのしかったです。","romaji":"ryokou wa totemo tanoshikatta desu.","hint":"putting it all together"}]},{"id":"adj-noun","section":"Describing Things","title":"Big, Small, New… (adj + noun)","grammar":"[い-adj][noun]  ·  どんな","grammarNote":"Put an い-adjective straight in front of the noun it describes: おおきい いえ = a big house. Ask “what kind of…?” with どんな.","vocab":[{"jp":"おおきい","romaji":"ookii","en":"big","pos":"adj"},{"jp":"ちいさい","romaji":"chiisai","en":"small","pos":"adj"},{"jp":"あたらしい","romaji":"atarashii","en":"new","pos":"adj"},{"jp":"ふるい","romaji":"furui","en":"old (things)","pos":"adj"},{"jp":"いえ","romaji":"ie","en":"house","pos":"n"},{"jp":"どんな","romaji":"donna","en":"what kind of","pos":"adj"}],"sentences":[{"en":"It's a big house.","jp":"おおきい いえです。","romaji":"ookii ie desu.","hint":""},{"en":"It's a small car.","jp":"ちいさい くるまです。","romaji":"chiisai kuruma desu.","hint":""},{"en":"It's a new house.","jp":"あたらしい いえです。","romaji":"atarashii ie desu.","hint":""},{"en":"It's an old book.","jp":"ふるい ほんです。","romaji":"furui hon desu.","hint":""},{"en":"What kind of car (is it)?","jp":"どんな くるまですか？","romaji":"donna kuruma desu ka?","hint":"どんな = what kind of"},{"en":"It's a big town.","jp":"おおきい まちです。","romaji":"ookii machi desu.","hint":""}]},{"id":"na-adj","section":"Describing Things","title":"な-adjectives (きれい・げんき)","grammar":"な-adjectives  ·  [adj]な [noun]","grammarNote":"な-adjectives don't end in a meaningful い. They take な before a noun (しずかな まち = a quiet town), but need no な before です (しずかです).","vocab":[{"jp":"きれい","romaji":"kirei","en":"pretty / clean","pos":"adj"},{"jp":"げんき","romaji":"genki","en":"well / energetic","pos":"adj"},{"jp":"しずか","romaji":"shizuka","en":"quiet","pos":"adj"},{"jp":"ゆうめい","romaji":"yuumei","en":"famous","pos":"adj"},{"jp":"まち","romaji":"machi","en":"town","pos":"n"},{"jp":"はな","romaji":"hana","en":"flower","pos":"n"}],"sentences":[{"en":"It's pretty.","jp":"きれいです。","romaji":"kirei desu.","hint":""},{"en":"Are you well?","jp":"げんきですか？","romaji":"genki desu ka?","hint":"a super common greeting"},{"en":"It's a quiet town.","jp":"しずかな まちです。","romaji":"shizukana machi desu.","hint":"な links a な-adj to a noun"},{"en":"It's famous.","jp":"ゆうめいです。","romaji":"yuumei desu.","hint":""},{"en":"It's a pretty flower.","jp":"きれいな はなです。","romaji":"kireina hana desu.","hint":""},{"en":"Sushi is famous.","jp":"おすしは ゆうめいです。","romaji":"osushi wa yuumei desu.","hint":""}]},{"id":"adj-negative","section":"Describing Things","title":"Not So… (〜くない／〜じゃない)","grammar":"い-adj 〜くない  ·  な-adj/noun じゃない","grammarNote":"Make an い-adjective negative by dropping い and adding 〜くない (たかい→たかくない). いい is irregular → よくない. な-adjectives and nouns use 〜じゃ ない instead.","vocab":[{"jp":"あつい","romaji":"atsui","en":"hot","pos":"adj"},{"jp":"さむい","romaji":"samui","en":"cold (weather)","pos":"adj"},{"jp":"たかくない","romaji":"takakunai","en":"not expensive","pos":"adj"},{"jp":"おいしくない","romaji":"oishikunai","en":"not tasty","pos":"adj"},{"jp":"よくない","romaji":"yokunai","en":"not good","pos":"adj"},{"jp":"あまり","romaji":"amari","en":"not very (+ neg)","pos":"adv"}],"sentences":[{"en":"It's not expensive.","jp":"たかくないです。","romaji":"takakunai desu.","hint":"い-adj negative = 〜くない"},{"en":"It isn't tasty.","jp":"おいしくないです。","romaji":"oishikunai desu.","hint":""},{"en":"It's hot.","jp":"あついです。","romaji":"atsui desu.","hint":""},{"en":"It's not cold.","jp":"さむくないです。","romaji":"samukunai desu.","hint":""},{"en":"It's not very good.","jp":"あまり よくないです。","romaji":"amari yokunai desu.","hint":"いい → よくない (irregular)"},{"en":"It's not quiet.","jp":"しずかじゃ ないです。","romaji":"shizuka ja nai desu.","hint":"な-adj → じゃ ない"}]}]},{"id":"L2","name":"Level 2","title":"Connecting & Doing","lessons":[{"id":"te-form","section":"The て-form","title":"The て-form","grammar":"verb → 〜て","grammarNote":"The て-form is the connector verb. Build it from the dictionary form: る-verbs drop る (たべる→たべて); う/つ/る→って, む/ぶ/ぬ→んで, く→いて, ぐ→いで, す→して. する→して, くる→きて, いく→いって (irregular). On its own it's a quick casual request: みて！ = “look!”","vocab":[{"jp":"みて","romaji":"mite","en":"look / watch  (見る)","pos":"v"},{"jp":"まって","romaji":"matte","en":"wait  (待つ)","pos":"v"},{"jp":"きいて","romaji":"kiite","en":"listen / ask  (聞く)","pos":"v"},{"jp":"きて","romaji":"kite","en":"come  (来る)","pos":"v"},{"jp":"やめて","romaji":"yamete","en":"stop it  (やめる)","pos":"v"},{"jp":"こっち","romaji":"kocchi","en":"over here / this way","pos":"n"},{"jp":"がんばって","romaji":"ganbatte","en":"hang in there / go for it  (頑張る)","pos":"v"}],"sentences":[{"en":"Look!","jp":"みて！","romaji":"mite!","hint":"bare て-form = casual request"},{"en":"Wait!","jp":"まって！","romaji":"matte!","hint":"add ください to be polite (next lesson)"},{"en":"Hey, listen.","jp":"ちょっと きいて。","romaji":"chotto kiite.","hint":""},{"en":"Come here.","jp":"こっち きて。","romaji":"kocchi kite.","hint":""},{"en":"Stop it.","jp":"やめて。","romaji":"yamete.","hint":""},{"en":"Hang in there!","jp":"がんばって！","romaji":"ganbatte!","hint":""},{"en":"Look at this.","jp":"これ みて。","romaji":"kore mite.","hint":""}]},{"id":"te-please","section":"The て-form","title":"Please Do X (〜てください)","grammar":"〜てください","grammarNote":"Add ください to a verb's て-form to politely ask someone to do something. These are the phrases you'll lean on most as a learner and traveller.","vocab":[{"jp":"まって","romaji":"matte","en":"wait  (待つ)","pos":"v"},{"jp":"いって","romaji":"itte","en":"say it  (言う)","pos":"v"},{"jp":"はなして","romaji":"hanashite","en":"speak / talk  (話す)","pos":"v"},{"jp":"おしえて","romaji":"oshiete","en":"tell / teach me  (教える)","pos":"v"},{"jp":"ゆっくり","romaji":"yukkuri","en":"slowly","pos":"adv"},{"jp":"もう いちど","romaji":"mou ichido","en":"once more","pos":"adv"},{"jp":"たすけて","romaji":"tasukete","en":"help me  (助ける)","pos":"v"}],"sentences":[{"en":"Please wait a moment.","jp":"ちょっと まって ください。","romaji":"chotto matte kudasai.","hint":""},{"en":"Please say it once more.","jp":"もう いちど いって ください。","romaji":"mou ichido itte kudasai.","hint":"lifesaver when you didn't catch it"},{"en":"Please speak slowly.","jp":"ゆっくり はなして ください。","romaji":"yukkuri hanashite kudasai.","hint":""},{"en":"Please tell me.","jp":"おしえて ください。","romaji":"oshiete kudasai.","hint":""},{"en":"Please help me.","jp":"たすけて ください。","romaji":"tasukete kudasai.","hint":"たすける = to help"},{"en":"Please say it slowly.","jp":"ゆっくり いって ください。","romaji":"yukkuri itte kudasai.","hint":""},{"en":"Please tell me once more.","jp":"もう いちど おしえて ください。","romaji":"mou ichido oshiete kudasai.","hint":""}]},{"id":"te-iru","section":"The て-form","title":"In Progress (〜ています)","grammar":"〜ています","grammarNote":"て-form + います describes an action happening right now (たべています = “I'm eating”) or an ongoing state (すんでいます = “I live”). Casually, drop the い: なにしてる？ = “what're you up to?”","vocab":[{"jp":"たべて","romaji":"tabete","en":"eating  (食べる)","pos":"v"},{"jp":"みて","romaji":"mite","en":"watching  (見る)","pos":"v"},{"jp":"よんで","romaji":"yonde","en":"reading  (読む)","pos":"v"},{"jp":"すんで","romaji":"sunde","en":"living  (住む)","pos":"v"},{"jp":"はたらいて","romaji":"hataraite","en":"working  (働く)","pos":"v"},{"jp":"して","romaji":"shite","en":"doing  (する)","pos":"v"},{"jp":"のんで","romaji":"nonde","en":"drinking  (飲む)","pos":"v"}],"sentences":[{"en":"What are you doing?","jp":"なにを して いますか？","romaji":"nani o shite imasu ka?","hint":"casual: なにしてる？"},{"en":"I'm eating right now.","jp":"いま たべて います。","romaji":"ima tabete imasu.","hint":""},{"en":"I'm watching TV.","jp":"テレビを みて います。","romaji":"terebi o mite imasu.","hint":""},{"en":"I live in Tokyo.","jp":"とうきょうに すんで います。","romaji":"toukyou ni sunde imasu.","hint":"すむ = to live → ongoing state"},{"en":"I work at a bank.","jp":"ぎんこうで はたらいて います。","romaji":"ginkou de hataraite imasu.","hint":""},{"en":"I'm reading a book.","jp":"ほんを よんで います。","romaji":"hon o yonde imasu.","hint":""},{"en":"I'm drinking coffee.","jp":"コーヒーを のんで います。","romaji":"koohii o nonde imasu.","hint":""}]},{"id":"because","section":"Linking Ideas","title":"Because / So (〜から・〜ので)","grammar":"〜から  ·  〜ので","grammarNote":"Put から after the reason, then the result: [reason]から、[result]。 ので is a softer, more polite “since”. The reason always comes first — the opposite order from English.","vocab":[{"jp":"つかれた","romaji":"tsukareta","en":"(I'm) tired","pos":"adj"},{"jp":"いそがしい","romaji":"isogashii","en":"busy","pos":"adj"},{"jp":"たかい","romaji":"takai","en":"expensive","pos":"adj"},{"jp":"やすい","romaji":"yasui","en":"cheap","pos":"adj"},{"jp":"さむい","romaji":"samui","en":"cold","pos":"adj"},{"jp":"どうして","romaji":"doushite","en":"why","pos":"adv"},{"jp":"あめ","romaji":"ame","en":"rain","pos":"n"}],"sentences":[{"en":"I'm tired, so I'm going home.","jp":"つかれたから、かえります。","romaji":"tsukareta kara, kaerimasu.","hint":""},{"en":"It's expensive, so I won't buy it.","jp":"たかいから、かいません。","romaji":"takai kara, kaimasen.","hint":""},{"en":"I'm busy today, so sorry.","jp":"きょうは いそがしいので、すみません。","romaji":"kyou wa isogashii node, sumimasen.","hint":"ので = softer “since”"},{"en":"It's cold, so let's head home.","jp":"さむいから、かえりましょう。","romaji":"samui kara, kaerimashou.","hint":""},{"en":"It's cheap, so I'll buy it.","jp":"やすいから、かいます。","romaji":"yasui kara, kaimasu.","hint":""},{"en":"Why? — Because it's tasty.","jp":"どうして？ — おいしいから。","romaji":"doushite? — oishii kara.","hint":""},{"en":"It's raining, so I'm not going.","jp":"あめだから、いきません。","romaji":"ame da kara, ikimasen.","hint":""}]},{"id":"but-kedo","section":"Linking Ideas","title":"But / Though (〜が・〜けど)","grammar":"〜が  ·  〜けど","grammarNote":"Join two clauses with が or けど for “but / though”: [clause]が、[contrasting clause]。 けど is the everyday, casual one; が is a touch more formal.","vocab":[{"jp":"たかい","romaji":"takai","en":"expensive","pos":"adj"},{"jp":"ほしい","romaji":"hoshii","en":"want (it)","pos":"adj"},{"jp":"おかね","romaji":"okane","en":"money","pos":"n"},{"jp":"むずかしい","romaji":"muzukashii","en":"difficult","pos":"adj"},{"jp":"たのしい","romaji":"tanoshii","en":"fun","pos":"adj"},{"jp":"けど","romaji":"kedo","en":"but / though","pos":"conj"},{"jp":"じかん","romaji":"jikan","en":"time","pos":"n"}],"sentences":[{"en":"It's expensive, but I'll buy it.","jp":"たかいですが、かいます。","romaji":"takai desu ga, kaimasu.","hint":""},{"en":"It's pricey, but tasty.","jp":"たかいけど、おいしい。","romaji":"takai kedo, oishii.","hint":""},{"en":"I want it, but I have no money.","jp":"ほしいけど、おかねが ない。","romaji":"hoshii kedo, okane ga nai.","hint":""},{"en":"Japanese is hard, but fun.","jp":"にほんごは むずかしいけど、たのしい。","romaji":"nihongo wa muzukashii kedo, tanoshii.","hint":""},{"en":"Sorry, but I don't understand.","jp":"すみませんが、わかりません。","romaji":"sumimasen ga, wakarimasen.","hint":""},{"en":"It's cheap, but tasty.","jp":"やすいけど、おいしい。","romaji":"yasui kedo, oishii.","hint":""},{"en":"I want to, but there's no time.","jp":"ほしいけど、じかんが ない。","romaji":"hoshii kedo, jikan ga nai.","hint":""}]},{"id":"permission","section":"Linking Ideas","title":"May I? / You Mustn't (〜てもいい・〜ては だめ)","grammar":"〜てもいいですか  ·  〜ては だめ／いけません","grammarNote":"て-form + もいいですか asks permission (“may I…?”). て-form + は だめ／いけません says it's not allowed. どうぞ is the friendly “go ahead”.","vocab":[{"jp":"とって","romaji":"totte","en":"take (a photo)  (撮る)","pos":"v"},{"jp":"すわって","romaji":"suwatte","en":"sit  (座る)","pos":"v"},{"jp":"さわって","romaji":"sawatte","en":"touch  (触る)","pos":"v"},{"jp":"しゃしん","romaji":"shashin","en":"photo","pos":"n"},{"jp":"どうぞ","romaji":"douzo","en":"go ahead / please","pos":"expr"},{"jp":"はいって","romaji":"haitte","en":"enter / come in  (入る)","pos":"v"},{"jp":"たばこ","romaji":"tabako","en":"tobacco / smoking","pos":"n"}],"sentences":[{"en":"May I take a photo here?","jp":"ここで しゃしんを とっても いいですか？","romaji":"koko de shashin o totte mo ii desu ka?","hint":""},{"en":"May I sit here?","jp":"ここに すわっても いいですか？","romaji":"koko ni suwatte mo ii desu ka?","hint":""},{"en":"Sure, go ahead.","jp":"どうぞ。","romaji":"douzo.","hint":""},{"en":"You can't take photos here.","jp":"ここで しゃしんを とっては いけません。","romaji":"koko de shashin o totte wa ikemasen.","hint":"〜ては いけません = not allowed"},{"en":"Don't touch, please.","jp":"さわっては だめです。","romaji":"sawatte wa dame desu.","hint":""},{"en":"May I come in?","jp":"はいっても いいですか？","romaji":"haitte mo ii desu ka?","hint":""},{"en":"No smoking here.","jp":"ここで たばこは だめです。","romaji":"koko de tabako wa dame desu.","hint":""}]},{"id":"sequence-te","section":"Linking Ideas","title":"Do A, Then B (〜て、… ・ 〜たり)","grammar":"〜て、〜  ·  〜たり〜たり","grammarNote":"Chain actions with the て-form: A して、B して、C します。 For a loose “things like A and B” list, use 〜たり〜たり して/します.","vocab":[{"jp":"おきて","romaji":"okite","en":"get up  (起きる)","pos":"v"},{"jp":"でかけて","romaji":"dekakete","en":"go out  (出かける)","pos":"v"},{"jp":"かえって","romaji":"kaette","en":"go back  (帰る)","pos":"v"},{"jp":"やすんで","romaji":"yasunde","en":"rest  (休む)","pos":"v"},{"jp":"あそんで","romaji":"asonde","en":"hang out / play  (遊ぶ)","pos":"v"},{"jp":"しゅうまつ","romaji":"shuumatsu","en":"weekend","pos":"n"},{"jp":"おふろ","romaji":"ofuro","en":"bath","pos":"n"}],"sentences":[{"en":"I get up, eat, and head out.","jp":"おきて、たべて、でかけます。","romaji":"okite, tabete, dekakemasu.","hint":""},{"en":"I'll go home and rest.","jp":"かえって、やすみます。","romaji":"kaette, yasumimasu.","hint":""},{"en":"Let's grab food and hang out.","jp":"ごはんを たべて、あそびましょう。","romaji":"gohan o tabete, asobimashou.","hint":""},{"en":"On weekends I read and watch movies and such.","jp":"しゅうまつは、ほんを よんだり えいがを みたり します。","romaji":"shuumatsu wa, hon o yondari eiga o mitari shimasu.","hint":"〜たり〜たり = “things like…”"},{"en":"I get up in the morning and drink coffee.","jp":"あさ おきて、コーヒーを のみます。","romaji":"asa okite, koohii o nomimasu.","hint":""},{"en":"I take a bath and go to bed.","jp":"おふろに はいって、ねます。","romaji":"ofuro ni haitte, nemasu.","hint":""},{"en":"On weekends I hang out and rest and such.","jp":"しゅうまつは、あそんだり やすんだり します。","romaji":"shuumatsu wa, asondari yasundari shimasu.","hint":""}]},{"id":"timing","section":"Linking Ideas","title":"When / Before / After (〜とき・まえに・あとで)","grammar":"〜とき  ·  〜まえに  ·  〜あとで","grammarNote":"[verb/plain]とき = “when…”. [dictionary verb]まえに = “before doing…”. [noun]の あとで = “after…”. Nouns also take の: しょくじの まえに = “before the meal”.","vocab":[{"jp":"ねる","romaji":"neru","en":"sleep / go to bed  (寝る)","pos":"v"},{"jp":"まえに","romaji":"mae ni","en":"before","pos":"conj"},{"jp":"あとで","romaji":"ato de","en":"after / later","pos":"conj"},{"jp":"ひま","romaji":"hima","en":"free (time)","pos":"adj"},{"jp":"しょくじ","romaji":"shokuji","en":"a meal","pos":"n"},{"jp":"でんわ","romaji":"denwa","en":"phone / a call","pos":"n"},{"jp":"は","romaji":"ha","en":"teeth  (歯)","pos":"n"}],"sentences":[{"en":"I brush my teeth before bed.","jp":"ねるまえに、はを みがきます。","romaji":"neru mae ni, ha o migakimasu.","hint":""},{"en":"Let's talk after the meal.","jp":"しょくじの あとで、はなしましょう。","romaji":"shokuji no ato de, hanashimashou.","hint":""},{"en":"When I'm free, I watch movies.","jp":"ひまな とき、えいがを みます。","romaji":"hima na toki, eiga o mimasu.","hint":""},{"en":"Wash your hands before you eat.","jp":"たべるまえに、てを あらって ください。","romaji":"taberu mae ni, te o aratte kudasai.","hint":""},{"en":"I'll call you later.","jp":"あとで でんわします。","romaji":"ato de denwa shimasu.","hint":""},{"en":"Please call before you head out.","jp":"でかけるまえに、でんわして ください。","romaji":"dekakeru mae ni, denwa shite kudasai.","hint":""},{"en":"When you're free, let's hang out.","jp":"ひまな とき、あそびましょう。","romaji":"hima na toki, asobimashou.","hint":""}]}]},{"id":"L3","name":"Level 3","title":"Getting Around","lessons":[{"id":"directions","section":"Finding Your Way","title":"Directions (みぎ・ひだり・まっすぐ)","grammar":"〜を みぎ／ひだりに まがる  ·  まっすぐ","grammarNote":"まっすぐ = straight ahead, みぎ = right, ひだり = left. To say “turn right at X”, use [place]を みぎに まがって ください. つぎの = the next….","vocab":[{"jp":"みぎ","romaji":"migi","en":"right","pos":"n"},{"jp":"ひだり","romaji":"hidari","en":"left","pos":"n"},{"jp":"まっすぐ","romaji":"massugu","en":"straight ahead","pos":"adv"},{"jp":"まがって","romaji":"magatte","en":"turn  (曲がる)","pos":"v"},{"jp":"つぎ","romaji":"tsugi","en":"next","pos":"n"},{"jp":"しんごう","romaji":"shingou","en":"traffic light","pos":"n"},{"jp":"こうさてん","romaji":"kousaten","en":"intersection  (交差点)","pos":"n"},{"jp":"むこう","romaji":"mukou","en":"the other side / over there","pos":"n"}],"sentences":[{"en":"Go straight, please.","jp":"まっすぐ いって ください。","romaji":"massugu itte kudasai.","hint":""},{"en":"Turn right at the next light.","jp":"つぎの しんごうを みぎに まがって ください。","romaji":"tsugi no shingou o migi ni magatte kudasai.","hint":""},{"en":"Turn left here.","jp":"ここで ひだりに まがって ください。","romaji":"koko de hidari ni magatte kudasai.","hint":""},{"en":"It's on the right.","jp":"みぎに あります。","romaji":"migi ni arimasu.","hint":""},{"en":"The station is straight ahead.","jp":"えきは まっすぐです。","romaji":"eki wa massugu desu.","hint":""},{"en":"Turn left at the next intersection.","jp":"つぎの こうさてんを ひだりに まがって ください。","romaji":"tsugi no kousaten o hidari ni magatte kudasai.","hint":""},{"en":"It's on the left.","jp":"ひだりに あります。","romaji":"hidari ni arimasu.","hint":""},{"en":"It's on the other side of the station.","jp":"えきの むこうです。","romaji":"eki no mukou desu.","hint":""}]},{"id":"transport","section":"Finding Your Way","title":"Getting There (〜で・〜から〜まで)","grammar":"[vehicle]で いきます  ·  〜から〜まで","grammarNote":"で marks the means: でんしゃで = by train. 〜から〜まで = from … to …. のりかえ = a transfer/change. あるいて = on foot.","vocab":[{"jp":"でんしゃ","romaji":"densha","en":"train","pos":"n"},{"jp":"バス","romaji":"basu","en":"bus","pos":"n"},{"jp":"タクシー","romaji":"takushii","en":"taxi","pos":"n"},{"jp":"あるいて","romaji":"aruite","en":"on foot / walking  (歩く)","pos":"v"},{"jp":"のりかえ","romaji":"norikae","en":"transfer / change","pos":"n"},{"jp":"くうこう","romaji":"kuukou","en":"airport","pos":"n"},{"jp":"ちかてつ","romaji":"chikatetsu","en":"subway  (地下鉄)","pos":"n"},{"jp":"じてんしゃ","romaji":"jitensha","en":"bicycle","pos":"n"}],"sentences":[{"en":"I'll go by train.","jp":"でんしゃで いきます。","romaji":"densha de ikimasu.","hint":""},{"en":"Let's take a taxi.","jp":"タクシーで いきましょう。","romaji":"takushii de ikimashou.","hint":""},{"en":"I'll walk.","jp":"あるいて いきます。","romaji":"aruite ikimasu.","hint":""},{"en":"From Tokyo to Osaka.","jp":"とうきょうから おおさかまで。","romaji":"toukyou kara oosaka made.","hint":""},{"en":"Where do I transfer?","jp":"どこで のりかえですか？","romaji":"doko de norikae desu ka?","hint":""},{"en":"I'll take the bus to the airport.","jp":"くうこうまで バスで いきます。","romaji":"kuukou made basu de ikimasu.","hint":""},{"en":"Let's take the subway.","jp":"ちかてつで いきましょう。","romaji":"chikatetsu de ikimashou.","hint":""},{"en":"I go to the station by bicycle.","jp":"じてんしゃで えきまで いきます。","romaji":"jitensha de eki made ikimasu.","hint":""}]},{"id":"does-this-go","section":"Finding Your Way","title":"Does This Go to…? (〜に いきますか)","grammar":"この〜は [place]に いきますか","grammarNote":"Point and ask: この バスは [place]に いきますか？ = “Does this bus go to …?” Swap バス for でんしゃ. でぐち = exit, ホーム = platform.","vocab":[{"jp":"この","romaji":"kono","en":"this …","pos":"adj"},{"jp":"でぐち","romaji":"deguchi","en":"exit","pos":"n"},{"jp":"ホーム","romaji":"hoomu","en":"platform","pos":"n"},{"jp":"ばんせん","romaji":"bansen","en":"track / platform no.","pos":"n"},{"jp":"くうこう","romaji":"kuukou","en":"airport","pos":"n"},{"jp":"しぶや","romaji":"shibuya","en":"Shibuya","pos":"n"},{"jp":"バス","romaji":"basu","en":"bus","pos":"n"},{"jp":"でんしゃ","romaji":"densha","en":"train","pos":"n"}],"sentences":[{"en":"Does this bus go to the station?","jp":"この バスは えきに いきますか？","romaji":"kono basu wa eki ni ikimasu ka?","hint":""},{"en":"Does this train go to the airport?","jp":"この でんしゃは くうこうに いきますか？","romaji":"kono densha wa kuukou ni ikimasu ka?","hint":""},{"en":"Where's the exit?","jp":"でぐちは どこですか？","romaji":"deguchi wa doko desu ka?","hint":""},{"en":"Which platform?","jp":"なんばんせんですか？","romaji":"nan-bansen desu ka?","hint":""},{"en":"Is Shibuya this platform?","jp":"しぶやは この ホームですか？","romaji":"shibuya wa kono hoomu desu ka?","hint":""},{"en":"Does this train go to Shibuya?","jp":"この でんしゃは しぶやに いきますか？","romaji":"kono densha wa shibuya ni ikimasu ka?","hint":""},{"en":"Does this bus go to the airport?","jp":"この バスは くうこうに いきますか？","romaji":"kono basu wa kuukou ni ikimasu ka?","hint":""},{"en":"Is the exit to the right?","jp":"でぐちは みぎですか？","romaji":"deguchi wa migi desu ka?","hint":""}]},{"id":"how-far","section":"Finding Your Way","title":"How Far / How Long (どのくらい)","grammar":"〜まで どのくらい かかりますか","grammarNote":"どのくらい = “how much / how long”. かかります = it takes (time or money). ぐらい = about/approximately. あるいて [time] = [time] on foot.","vocab":[{"jp":"どのくらい","romaji":"dono kurai","en":"how long / how far","pos":"adv"},{"jp":"かかります","romaji":"kakarimasu","en":"it takes  (かかる)","pos":"v"},{"jp":"ふん","romaji":"fun","en":"minutes  (〜分)","pos":"n"},{"jp":"ぐらい","romaji":"gurai","en":"about / approximately","pos":"prt"},{"jp":"とおい","romaji":"tooi","en":"far","pos":"adj"},{"jp":"ちかい","romaji":"chikai","en":"near / close","pos":"adj"},{"jp":"あるいて","romaji":"aruite","en":"on foot / walking","pos":"adv"},{"jp":"いちじかん","romaji":"ichi-jikan","en":"one hour","pos":"n"}],"sentences":[{"en":"How long does it take to the station?","jp":"えきまで どのくらい かかりますか？","romaji":"eki made dono kurai kakarimasu ka?","hint":""},{"en":"It takes about ten minutes.","jp":"じゅっぷんぐらい かかります。","romaji":"juppun gurai kakarimasu.","hint":""},{"en":"Is it far?","jp":"とおいですか？","romaji":"tooi desu ka?","hint":""},{"en":"No, it's close.","jp":"いいえ、ちかいです。","romaji":"iie, chikai desu.","hint":""},{"en":"It's about five minutes on foot.","jp":"あるいて ごふんぐらいです。","romaji":"aruite go-fun gurai desu.","hint":""},{"en":"How long does it take to the airport?","jp":"くうこうまで どのくらい かかりますか？","romaji":"kuukou made donokurai kakarimasu ka?","hint":""},{"en":"It takes about an hour.","jp":"いちじかんぐらい かかります。","romaji":"ichi-jikan gurai kakarimasu.","hint":""},{"en":"About twenty minutes by bus.","jp":"バスで にじゅっぷんぐらいです。","romaji":"basu de nijuppun gurai desu.","hint":""}]},{"id":"tickets","section":"Tickets & Trouble","title":"Buying Tickets (〜まで 〜まい)","grammar":"[place]まで [number]まい  ·  おうふく／かたみち","grammarNote":"At the counter: [destination]まで [count]まい おねがいします。 まい counts flat things like tickets. おうふく = round trip, かたみち = one-way.","vocab":[{"jp":"きっぷ","romaji":"kippu","en":"ticket","pos":"n"},{"jp":"まい","romaji":"mai","en":"[counter: tickets]","pos":"n"},{"jp":"おとな","romaji":"otona","en":"adult","pos":"n"},{"jp":"おうふく","romaji":"oufuku","en":"round trip","pos":"n"},{"jp":"かたみち","romaji":"katamichi","en":"one-way","pos":"n"},{"jp":"かいます","romaji":"kaimasu","en":"buy  (買う)","pos":"v"},{"jp":"おねがいします","romaji":"onegai shimasu","en":"please (request)","pos":"expr"},{"jp":"こども","romaji":"kodomo","en":"child","pos":"n"}],"sentences":[{"en":"One ticket to Shinjuku, please.","jp":"しんじゅくまで いちまい おねがいします。","romaji":"shinjuku made ichi-mai onegai shimasu.","hint":""},{"en":"Two tickets to Kyoto, please.","jp":"きょうとまで にまい おねがいします。","romaji":"kyouto made ni-mai onegai shimasu.","hint":""},{"en":"One adult, please.","jp":"おとな いちまい おねがいします。","romaji":"otona ichi-mai onegai shimasu.","hint":""},{"en":"Round trip, please.","jp":"おうふくで おねがいします。","romaji":"oufuku de onegai shimasu.","hint":""},{"en":"One-way is fine.","jp":"かたみちで いいです。","romaji":"katamichi de ii desu.","hint":""},{"en":"Where do I buy tickets?","jp":"きっぷは どこで かいますか？","romaji":"kippu wa doko de kaimasu ka?","hint":""},{"en":"Two children's tickets, please.","jp":"こども にまい おねがいします。","romaji":"kodomo ni-mai onegaishimasu.","hint":""},{"en":"How much is a round trip?","jp":"おうふくは いくらですか？","romaji":"oufuku wa ikura desu ka?","hint":""}]},{"id":"travel-trouble","section":"Tickets & Trouble","title":"When Things Go Wrong (まよう・なくす)","grammar":"みちに まよう  ·  〜に のりおくれる  ·  〜を なくす","grammarNote":"みちに まよいました = “I'm lost.” [train]に のりおくれました = “I missed the …”. [thing]を なくしました = “I lost my …”. Pair with すみません to get help fast.","vocab":[{"jp":"みち","romaji":"michi","en":"road / the way","pos":"n"},{"jp":"まよいました","romaji":"mayoimashita","en":"got lost  (迷う)","pos":"v"},{"jp":"のりおくれました","romaji":"noriokuremashita","en":"missed (a train/bus)  (乗り遅れる)","pos":"v"},{"jp":"さいふ","romaji":"saifu","en":"wallet","pos":"n"},{"jp":"なくしました","romaji":"nakushimashita","en":"lost (an item)  (なくす)","pos":"v"},{"jp":"こまって","romaji":"komatte","en":"in trouble / stuck  (困る)","pos":"v"},{"jp":"けいたい","romaji":"keitai","en":"mobile phone  (携帯)","pos":"n"},{"jp":"わすれました","romaji":"wasuremashita","en":"forgot / left behind  (忘れました)","pos":"v"}],"sentences":[{"en":"I'm lost.","jp":"みちに まよいました。","romaji":"michi ni mayoimashita.","hint":""},{"en":"I missed the train.","jp":"でんしゃに のりおくれました。","romaji":"densha ni noriokuremashita.","hint":""},{"en":"I lost my wallet.","jp":"さいふを なくしました。","romaji":"saifu o nakushimashita.","hint":""},{"en":"Please help me.","jp":"たすけて ください。","romaji":"tasukete kudasai.","hint":""},{"en":"I'm stuck — where's the station?","jp":"こまって います。えきは どこですか？","romaji":"komatte imasu. eki wa doko desu ka?","hint":""},{"en":"I lost my phone.","jp":"けいたいを なくしました。","romaji":"keitai o nakushimashita.","hint":""},{"en":"I forgot my ticket.","jp":"きっぷを わすれました。","romaji":"kippu o wasuremashita.","hint":""},{"en":"I missed the bus.","jp":"バスに のりおくれました。","romaji":"basu ni noriokuremashita.","hint":""}]},{"id":"had-better","section":"Tickets & Trouble","title":"You'd Better… (〜たほうがいい)","grammar":"〜た ほうがいい  ·  〜ない ほうがいい","grammarNote":"[verb た-form]ほうがいい = “you'd better / it's better to …” — friendly advice. The negative is [verb ない-form]ほうがいい = “better not to …”. きをつけて = take care!","vocab":[{"jp":"はやく","romaji":"hayaku","en":"soon / quickly","pos":"adv"},{"jp":"いった","romaji":"itta","en":"go (better to)  (行く)","pos":"v"},{"jp":"のった","romaji":"notta","en":"take / ride (better to)  (乗る)","pos":"v"},{"jp":"かさ","romaji":"kasa","en":"umbrella","pos":"n"},{"jp":"もっていった","romaji":"motte itta","en":"take (it) along  (持って行く)","pos":"v"},{"jp":"きをつけて","romaji":"ki o tsukete","en":"take care","pos":"expr"},{"jp":"やすんだ","romaji":"yasunda","en":"rest (better to)  (休んだ)","pos":"v"},{"jp":"きいた","romaji":"kiita","en":"ask (better to)  (聞いた)","pos":"v"}],"sentences":[{"en":"You'd better go soon.","jp":"はやく いった ほうが いいですよ。","romaji":"hayaku itta hou ga ii desu yo.","hint":""},{"en":"You'd better take a taxi.","jp":"タクシーに のった ほうが いいです。","romaji":"takushii ni notta hou ga ii desu.","hint":""},{"en":"You'd better take an umbrella.","jp":"かさを もっていった ほうが いいです。","romaji":"kasa o motte itta hou ga ii desu.","hint":""},{"en":"You'd better not go.","jp":"いかない ほうが いいです。","romaji":"ikanai hou ga ii desu.","hint":"ない-form = “better not to”"},{"en":"Take care!","jp":"きをつけて。","romaji":"ki o tsukete.","hint":""},{"en":"You'd better rest.","jp":"やすんだ ほうが いいですよ。","romaji":"yasunda hou ga ii desu yo.","hint":""},{"en":"You'd better ask at the station.","jp":"えきで きいた ほうが いいです。","romaji":"eki de kiita hou ga ii desu.","hint":""},{"en":"Better to go by taxi.","jp":"タクシーで いった ほうが いいです。","romaji":"takushii de itta hou ga ii desu.","hint":""}]}]},{"id":"L4","name":"Level 4","title":"Real Conversations","lessons":[{"id":"plain-form","section":"Talking Casually","title":"Casual Speech (plain form)","grammar":"plain form  ·  だ","grammarNote":"With friends, drop です／ます. たべます→たべる, いきます→いく; です→だ (or nothing). Questions just rise in tone — no か needed: なにする？ = “whatcha doing?”","vocab":[{"jp":"なに","romaji":"nani","en":"what","pos":"n"},{"jp":"する","romaji":"suru","en":"do  (します casual)","pos":"v"},{"jp":"いく","romaji":"iku","en":"go  (いきます casual)","pos":"v"},{"jp":"かえる","romaji":"kaeru","en":"go home  (帰る)","pos":"v"},{"jp":"たべる","romaji":"taberu","en":"eat  (食べる)","pos":"v"},{"jp":"だいじょうぶ","romaji":"daijoubu","en":"okay / fine","pos":"adj"}],"sentences":[{"en":"What are you doing today?","jp":"きょう、なにする？","romaji":"kyou, nani suru?","hint":""},{"en":"Where are you going?","jp":"どこ いくの？","romaji":"doko iku no?","hint":"の softens a casual question"},{"en":"I'm heading home.","jp":"かえる。","romaji":"kaeru.","hint":""},{"en":"What do you wanna eat?","jp":"なに たべる？","romaji":"nani taberu?","hint":""},{"en":"You okay?","jp":"だいじょうぶ？","romaji":"daijoubu?","hint":""},{"en":"Yeah, I'm fine.","jp":"うん、だいじょうぶ。","romaji":"un, daijoubu.","hint":""}]},{"id":"making-plans","section":"Talking Casually","title":"Making Plans (〜ない？・〜よう)","grammar":"〜ない？ (wanna…?)  ·  〜よう (let's)","grammarNote":"Casual invites: [verb]ない？ = “wanna …?” (いかない？ = “wanna go?”). Casual “let's” is the volitional 〜よう／〜おう: いこう = “let's go.” こんど = sometime / next time.","vocab":[{"jp":"こんど","romaji":"kondo","en":"sometime / next time","pos":"n"},{"jp":"いかない","romaji":"ikanai","en":"wanna go?  (行く)","pos":"v"},{"jp":"のみ","romaji":"nomi","en":"(to) drink  (飲む)","pos":"v"},{"jp":"いこう","romaji":"ikou","en":"let's go","pos":"v"},{"jp":"あおう","romaji":"aou","en":"let's meet  (会う)","pos":"v"},{"jp":"ひま","romaji":"hima","en":"free (time)","pos":"adj"}],"sentences":[{"en":"Wanna grab food sometime?","jp":"こんど ごはん いかない？","romaji":"kondo gohan ikanai?","hint":""},{"en":"Wanna go for a drink?","jp":"のみに いかない？","romaji":"nomi ni ikanai?","hint":""},{"en":"Let's go!","jp":"いこう！","romaji":"ikou!","hint":""},{"en":"You free this weekend?","jp":"しゅうまつ ひま？","romaji":"shuumatsu hima?","hint":""},{"en":"Let's meet at the station.","jp":"えきで あおう。","romaji":"eki de aou.","hint":""}]},{"id":"i-think","section":"Talking Casually","title":"I Think… (〜と おもう)","grammar":"[plain]と おもう／おもいます","grammarNote":"Give an opinion with plain form + と おもう: [sentence]と おもう = “I think (that) …”. What you think stays in plain form even when おもいます is polite.","vocab":[{"jp":"おもう","romaji":"omou","en":"think  (思う)","pos":"v"},{"jp":"あめ","romaji":"ame","en":"rain","pos":"n"},{"jp":"たぶん","romaji":"tabun","en":"probably / maybe","pos":"adv"},{"jp":"いい","romaji":"ii","en":"good","pos":"adj"},{"jp":"むり","romaji":"muri","en":"impossible / no way","pos":"adj"},{"jp":"そう","romaji":"sou","en":"so / that way","pos":"adv"}],"sentences":[{"en":"I think it'll rain tomorrow.","jp":"あした あめだと おもう。","romaji":"ashita ame da to omou.","hint":""},{"en":"I think that's good.","jp":"それは いいと おもう。","romaji":"sore wa ii to omou.","hint":""},{"en":"I think he'll come.","jp":"くると おもいます。","romaji":"kuru to omoimasu.","hint":""},{"en":"I don't think so.","jp":"そう おもわない。","romaji":"sou omowanai.","hint":""},{"en":"I think it's probably impossible.","jp":"たぶん むりだと おもう。","romaji":"tabun muri da to omou.","hint":""}]},{"id":"quoting","section":"Talking Casually","title":"They Said… (〜って・〜と いう)","grammar":"[plain]と いいました  ·  〜って","grammarNote":"Report speech with と いう: [words]と いいました = “(they) said …”. Casually って replaces と: こないって = “(they) said they're not coming.”","vocab":[{"jp":"って","romaji":"tte","en":"[casual quote: that]","pos":"prt"},{"jp":"いってた","romaji":"itteta","en":"said / was saying  (言う)","pos":"v"},{"jp":"なんて","romaji":"nante","en":"what (did you say)","pos":"adv"},{"jp":"いみ","romaji":"imi","en":"meaning","pos":"n"},{"jp":"どういう","romaji":"dou iu","en":"what kind of","pos":"adj"},{"jp":"しらない","romaji":"shiranai","en":"don't know  (知る)","pos":"v"}],"sentences":[{"en":"They said they're not coming tomorrow.","jp":"あした こないって いってた。","romaji":"ashita konai tte itteta.","hint":""},{"en":"What did you say?","jp":"なんて いった？","romaji":"nante itta?","hint":""},{"en":"What does this mean?","jp":"これ、どういう いみ？","romaji":"kore, dou iu imi?","hint":""},{"en":"I said it's fine.","jp":"いいって いった。","romaji":"ii tte itta.","hint":""},{"en":"I don't know their name.","jp":"なまえ、しらない。","romaji":"namae, shiranai.","hint":""}]},{"id":"favors","section":"Reacting & Relating","title":"Favors (あげる・くれる・もらう)","grammar":"〜て あげる／くれる／もらう","grammarNote":"Who does the favor for whom: あげる = I do it for someone; くれる = someone does it for me; もらう = I get someone to do it. With a て-form: かしてくれた = “(they) lent it to me.”","vocab":[{"jp":"あげる","romaji":"ageru","en":"do (for someone)","pos":"v"},{"jp":"くれる","romaji":"kureru","en":"do (for me)","pos":"v"},{"jp":"もらう","romaji":"morau","en":"get / receive","pos":"v"},{"jp":"かして","romaji":"kashite","en":"lend  (貸す)","pos":"v"},{"jp":"おしえて","romaji":"oshiete","en":"tell / teach  (教える)","pos":"v"},{"jp":"てつだって","romaji":"tetsudatte","en":"help out  (手伝う)","pos":"v"}],"sentences":[{"en":"A friend lent it to me.","jp":"ともだちが かしてくれた。","romaji":"tomodachi ga kashite kureta.","hint":""},{"en":"I had a friend teach me.","jp":"ともだちに おしえてもらった。","romaji":"tomodachi ni oshiete moratta.","hint":""},{"en":"I'll help you out.","jp":"てつだって あげる。","romaji":"tetsudatte ageru.","hint":""},{"en":"Thanks for coming.","jp":"きてくれて ありがとう。","romaji":"kite kurete arigatou.","hint":""},{"en":"Could you tell me?","jp":"おしえてくれる？","romaji":"oshiete kureru?","hint":""}]},{"id":"comparing","section":"Reacting & Relating","title":"Comparing (〜より・〜のほうが・いちばん)","grammar":"A より B の ほうが …  ·  いちばん","grammarNote":"A より B の ほうが [adj] = “B is more [adj] than A”. いちばん [adj] = “the most [adj] / the …-est”. どっち = which (of two).","vocab":[{"jp":"より","romaji":"yori","en":"than","pos":"prt"},{"jp":"ほう","romaji":"hou","en":"side / one (of options)","pos":"n"},{"jp":"いちばん","romaji":"ichiban","en":"the most / #1","pos":"adv"},{"jp":"どっち","romaji":"docchi","en":"which (of two)","pos":"n"},{"jp":"やすい","romaji":"yasui","en":"cheap","pos":"adj"},{"jp":"なつ","romaji":"natsu","en":"summer","pos":"n"}],"sentences":[{"en":"The bus is cheaper than the train.","jp":"でんしゃより バスの ほうが やすい。","romaji":"densha yori basu no hou ga yasui.","hint":""},{"en":"Which do you like better?","jp":"どっちが すき？","romaji":"docchi ga suki?","hint":""},{"en":"I like coffee better.","jp":"コーヒーの ほうが すき。","romaji":"koohii no hou ga suki.","hint":""},{"en":"I like summer best.","jp":"なつが いちばん すき。","romaji":"natsu ga ichiban suki.","hint":""},{"en":"This one's the cheapest.","jp":"これが いちばん やすい。","romaji":"kore ga ichiban yasui.","hint":""}]},{"id":"reactions","section":"Reacting & Relating","title":"Reactions & Aizuchi (そうなんだ・まじで)","grammar":"あいづち — reactions","grammarNote":"Aizuchi are the little reactions that show you're listening — sprinkle them in. そうなんだ = “oh really”, なるほど = “I see”, まじで = “seriously?”, すごい = “wow”.","vocab":[{"jp":"そうなんだ","romaji":"sou nanda","en":"oh, really / I see","pos":"expr"},{"jp":"なるほど","romaji":"naruhodo","en":"I see / makes sense","pos":"expr"},{"jp":"まじで","romaji":"maji de","en":"seriously? / for real","pos":"expr"},{"jp":"すごい","romaji":"sugoi","en":"wow / awesome","pos":"adj"},{"jp":"ほんとう","romaji":"hontou","en":"really / true","pos":"adj"},{"jp":"やばい","romaji":"yabai","en":"crazy / wow (slang)","pos":"adj"}],"sentences":[{"en":"Oh, really?","jp":"そうなんだ。","romaji":"sou nanda.","hint":""},{"en":"Wait, seriously!?","jp":"え、まじで！？","romaji":"e, maji de!?","hint":""},{"en":"I see, makes sense.","jp":"なるほど。","romaji":"naruhodo.","hint":""},{"en":"Wow, that's awesome!","jp":"すごい！","romaji":"sugoi!","hint":""},{"en":"Really? That's wild.","jp":"ほんとう？やばい。","romaji":"hontou? yabai.","hint":""}]}]},{"id":"L5","name":"Level 5","title":"Nuance & Plans","lessons":[{"id":"conditionals","section":"If & Necessity","title":"If / When (〜たら・〜なら)","grammar":"〜たら  ·  〜なら","grammarNote":"〜たら is the all-purpose “if/when”: take the past た-form and add ら — やすかったら = “if it's cheap”, ついたら = “when I arrive”. 〜なら = “if (that's the case)”, often reacting to what someone just said.","vocab":[{"jp":"たら","romaji":"tara","en":"if / when","pos":"conj"},{"jp":"なら","romaji":"nara","en":"if (that's so)","pos":"conj"},{"jp":"つく","romaji":"tsuku","en":"arrive  (着く)","pos":"v"},{"jp":"やすい","romaji":"yasui","en":"cheap","pos":"adj"},{"jp":"あめ","romaji":"ame","en":"rain","pos":"n"},{"jp":"ひま","romaji":"hima","en":"free (time)","pos":"adj"}],"sentences":[{"en":"If it's cheap, I'll buy it.","jp":"やすかったら、かう。","romaji":"yasukattara, kau.","hint":""},{"en":"Call me when you arrive.","jp":"ついたら、でんわして。","romaji":"tsuitara, denwa shite.","hint":""},{"en":"If it rains, I won't go.","jp":"あめだったら、いかない。","romaji":"ame dattara, ikanai.","hint":""},{"en":"If you're free, wanna come?","jp":"ひまなら、こない？","romaji":"hima nara, konai?","hint":""},{"en":"If it were me, I wouldn't go.","jp":"わたしなら、いかない。","romaji":"watashi nara, ikanai.","hint":""}]},{"id":"have-to","section":"If & Necessity","title":"Gotta / Don't Have To (〜なきゃ・〜なくてもいい)","grammar":"〜なきゃ／なければ ならない  ·  〜なくてもいい","grammarNote":"Obligation: 〜なければ ならない (formal) → casual 〜なきゃ／〜ないと: いかなきゃ = “I gotta go.” No obligation: [verb ない-stem]+なくてもいい = “you don't have to …”.","vocab":[{"jp":"なきゃ","romaji":"nakya","en":"gotta / must  (〜なければ)","pos":"aux"},{"jp":"おきる","romaji":"okiru","en":"get up  (起きる)","pos":"v"},{"jp":"べんきょう","romaji":"benkyou","en":"study","pos":"n"},{"jp":"いそぐ","romaji":"isogu","en":"hurry  (急ぐ)","pos":"v"},{"jp":"はらう","romaji":"harau","en":"pay  (払う)","pos":"v"},{"jp":"なくてもいい","romaji":"nakute mo ii","en":"don't have to","pos":"aux"}],"sentences":[{"en":"I gotta get up early tomorrow.","jp":"あした はやく おきなきゃ。","romaji":"ashita hayaku okinakya.","hint":""},{"en":"I have to study today.","jp":"きょう べんきょう しなきゃ。","romaji":"kyou benkyou shinakya.","hint":""},{"en":"We gotta hurry.","jp":"いそがなきゃ。","romaji":"isoganakya.","hint":""},{"en":"You don't have to come.","jp":"こなくてもいい。","romaji":"konakute mo ii.","hint":""},{"en":"You don't have to pay.","jp":"はらわなくてもいいよ。","romaji":"harawanakute mo ii yo.","hint":""}]},{"id":"potential","section":"If & Necessity","title":"Can Do It (〜られる・〜える)","grammar":"potential form 〜られる／〜える","grammarNote":"“Be able to”: る-verbs → 〜られる (たべる→たべられる); う-verbs shift the final sound to え + る (はなす→はなせる, いく→いける). する→できる, くる→こられる. The thing you can do takes が.","vocab":[{"jp":"はなせる","romaji":"hanaseru","en":"can speak  (話す)","pos":"v"},{"jp":"たべられる","romaji":"taberareru","en":"can eat  (食べる)","pos":"v"},{"jp":"いける","romaji":"ikeru","en":"can go  (行く)","pos":"v"},{"jp":"よめる","romaji":"yomeru","en":"can read  (読む)","pos":"v"},{"jp":"およげる","romaji":"oyogeru","en":"can swim  (泳ぐ)","pos":"v"},{"jp":"すこし","romaji":"sukoshi","en":"a little","pos":"adv"}],"sentences":[{"en":"I can speak Japanese.","jp":"にほんごが はなせる。","romaji":"nihongo ga hanaseru.","hint":""},{"en":"Can you eat natto?","jp":"なっとう たべられる？","romaji":"nattou taberareru?","hint":""},{"en":"I can't go tomorrow.","jp":"あした いけない。","romaji":"ashita ikenai.","hint":""},{"en":"Can you read kanji?","jp":"かんじ よめる？","romaji":"kanji yomeru?","hint":""},{"en":"I can swim a little.","jp":"すこし およげる。","romaji":"sukoshi oyogeru.","hint":""}]},{"id":"intend","section":"Plans & Impressions","title":"Planning To (〜つもり・〜よてい)","grammar":"〜つもり  ·  〜よてい","grammarNote":"[plain verb]つもり = “I intend / plan to …”. [verb]よてい = a scheduled plan. Negative intent: [verb ない-form]+つもり = “I don't plan to …”.","vocab":[{"jp":"つもり","romaji":"tsumori","en":"intend / plan to","pos":"n"},{"jp":"よてい","romaji":"yotei","en":"plan / schedule","pos":"n"},{"jp":"らいしゅう","romaji":"raishuu","en":"next week","pos":"n"},{"jp":"りゅうがく","romaji":"ryuugaku","en":"study abroad","pos":"n"},{"jp":"やめる","romaji":"yameru","en":"quit / stop  (やめる)","pos":"v"},{"jp":"なつ","romaji":"natsu","en":"summer","pos":"n"}],"sentences":[{"en":"I plan to go home next week.","jp":"らいしゅう かえる つもり。","romaji":"raishuu kaeru tsumori.","hint":""},{"en":"What do you plan to do?","jp":"どうする つもり？","romaji":"dou suru tsumori?","hint":""},{"en":"I'm planning to study abroad.","jp":"りゅうがくする よてい。","romaji":"ryuugaku suru yotei.","hint":""},{"en":"I don't plan to quit.","jp":"やめない つもり。","romaji":"yamenai tsumori.","hint":""},{"en":"I'm set to go to Japan in summer.","jp":"なつに にほんに いく よてい。","romaji":"natsu ni nihon ni iku yotei.","hint":""}]},{"id":"seems","section":"Plans & Impressions","title":"Looks / Seems Like (〜そう・〜みたい)","grammar":"〜そう  ·  〜みたい  ·  〜らしい","grammarNote":"By appearance: [adj stem]+そう = “looks …” (おいしそう = “looks tasty”). [plain]みたい = “seems like / like a …”. [plain]らしい = “apparently / I hear …”.","vocab":[{"jp":"そう","romaji":"sou","en":"looks (like)","pos":"aux"},{"jp":"みたい","romaji":"mitai","en":"seems / like","pos":"aux"},{"jp":"らしい","romaji":"rashii","en":"apparently / I hear","pos":"aux"},{"jp":"ふる","romaji":"furu","en":"fall (rain)  (降る)","pos":"v"},{"jp":"やすみ","romaji":"yasumi","en":"day off / closed","pos":"n"},{"jp":"いそがしい","romaji":"isogashii","en":"busy","pos":"adj"}],"sentences":[{"en":"That looks delicious!","jp":"おいしそう！","romaji":"oishisou!","hint":""},{"en":"Looks fun.","jp":"たのしそう。","romaji":"tanoshisou.","hint":""},{"en":"It looks like it'll rain.","jp":"あめが ふりそう。","romaji":"ame ga furisou.","hint":""},{"en":"Apparently it's closed today.","jp":"きょうは やすみらしい。","romaji":"kyou wa yasumi rashii.","hint":""},{"en":"He's like a kid.","jp":"こどもみたい。","romaji":"kodomo mitai.","hint":""},{"en":"She looks busy.","jp":"いそがしそう。","romaji":"isogashisō.","hint":""}]},{"id":"try-doing","section":"Plans & Impressions","title":"Give It a Try (〜てみる・〜ちゃう)","grammar":"〜てみる  ·  〜てしまう／〜ちゃう","grammarNote":"〜てみる = “try doing / give it a go” (たべてみる = “try eating it”). 〜てしまう = do completely or by accident; casual 〜ちゃう: わすれちゃった = “I forgot (oops).”","vocab":[{"jp":"みる","romaji":"miru","en":"try doing  (〜てみる)","pos":"v"},{"jp":"やる","romaji":"yaru","en":"do  (casual する)","pos":"v"},{"jp":"いちど","romaji":"ichido","en":"once / one time","pos":"n"},{"jp":"ちゃった","romaji":"chatta","en":"ended up / oops did  (〜てしまった)","pos":"aux"},{"jp":"わすれる","romaji":"wasureru","en":"forget  (忘れる)","pos":"v"},{"jp":"ぜんぶ","romaji":"zenbu","en":"all / everything","pos":"n"}],"sentences":[{"en":"Try eating it once.","jp":"いちど たべてみて。","romaji":"ichido tabete mite.","hint":""},{"en":"I'll give it a try.","jp":"やってみる。","romaji":"yatte miru.","hint":""},{"en":"Let's try going.","jp":"いってみよう。","romaji":"itte miyou.","hint":""},{"en":"I forgot (oops).","jp":"わすれちゃった。","romaji":"wasurechatta.","hint":""},{"en":"I ate it all up.","jp":"ぜんぶ たべちゃった。","romaji":"zenbu tabechatta.","hint":""}]},{"id":"experience","section":"Plans & Impressions","title":"Have You Ever…? (〜たことがある)","grammar":"[verb た-form]ことが ある","grammarNote":"[verb た-form]+ことが ある = “have done / have the experience of …”. Casual question: 〜たこと ある？ = “have you ever …?” Never: 〜たこと ない = “I've never …”.","vocab":[{"jp":"こと","romaji":"koto","en":"experience / the act","pos":"n"},{"jp":"ある","romaji":"aru","en":"have / there is","pos":"v"},{"jp":"ない","romaji":"nai","en":"haven't / there isn't","pos":"v"},{"jp":"すし","romaji":"sushi","en":"sushi","pos":"n"},{"jp":"のぼる","romaji":"noboru","en":"climb  (登る)","pos":"v"},{"jp":"ゆき","romaji":"yuki","en":"snow","pos":"n"}],"sentences":[{"en":"Have you ever had sushi?","jp":"すし たべたこと ある？","romaji":"sushi tabeta koto aru?","hint":""},{"en":"I've been to Japan.","jp":"にほんに いったことが ある。","romaji":"nihon ni itta koto ga aru.","hint":""},{"en":"I've never climbed Mt. Fuji.","jp":"ふじさんに のぼったこと ない。","romaji":"fujisan ni nobotta koto nai.","hint":""},{"en":"Have you seen this movie?","jp":"この えいが みたこと ある？","romaji":"kono eiga mita koto aru?","hint":""},{"en":"I've never seen snow.","jp":"ゆきを みたこと ない。","romaji":"yuki o mita koto nai.","hint":""}]}]},{"id":"L6","name":"Level 6","title":"Expert","lessons":[{"id":"passive","section":"Things Happen to You","title":"It Was Done to Me (passive 〜られる)","grammar":"passive 〜れる／〜られる","grammarNote":"Passive: う-verbs → 〜れる (いう→いわれる), る-verbs → 〜られる (みる→みられる); する→される, くる→こられる. The doer takes に. Often used for things done *to* you — frequently unwelcome (the “suffering passive”).","vocab":[{"jp":"おこられる","romaji":"okorareru","en":"be scolded  (怒られる)","pos":"v"},{"jp":"ぬすまれる","romaji":"nusumareru","en":"be stolen  (盗まれる)","pos":"v"},{"jp":"ほめられる","romaji":"homerareru","en":"be praised  (褒められる)","pos":"v"},{"jp":"たのまれる","romaji":"tanomareru","en":"be asked (a favor)  (頼まれる)","pos":"v"},{"jp":"ふられる","romaji":"furareru","en":"be rained on / dumped  (降られる)","pos":"v"},{"jp":"ぶちょう","romaji":"buchou","en":"department head / boss","pos":"n"}],"sentences":[{"en":"I was scolded by my boss.","jp":"ぶちょうに おこられた。","romaji":"buchou ni okorareta.","hint":""},{"en":"My wallet was stolen.","jp":"さいふを ぬすまれた。","romaji":"saifu o nusumareta.","hint":""},{"en":"I was praised by the teacher.","jp":"せんせいに ほめられた。","romaji":"sensei ni homerareta.","hint":""},{"en":"A friend asked me a favor.","jp":"ともだちに たのまれた。","romaji":"tomodachi ni tanomareta.","hint":""},{"en":"I got rained on on the way home.","jp":"かえりに あめに ふられた。","romaji":"kaeri ni ame ni furareta.","hint":"suffering passive — it happened *to* me"}]},{"id":"causative","section":"Things Happen to You","title":"Make / Let Someone Do (causative 〜させる)","grammar":"causative 〜せる／〜させる","grammarNote":"Causative = make or let someone do. う-verbs → 〜せる (まつ→またせる), る-verbs → 〜させる (たべる→たべさせる); する→させる, くる→こさせる. 〜させてください = “please let me …”.","vocab":[{"jp":"やらせる","romaji":"yaraseru","en":"let (someone) do","pos":"v"},{"jp":"またせる","romaji":"mataseru","en":"make wait  (待たせる)","pos":"v"},{"jp":"かんがえさせる","romaji":"kangaesaseru","en":"let (someone) think  (考えさせる)","pos":"v"},{"jp":"かかせる","romaji":"kakaseru","en":"make write  (書かせる)","pos":"v"},{"jp":"はらわせる","romaji":"harawaseru","en":"let (someone) pay  (払わせる)","pos":"v"},{"jp":"やすませる","romaji":"yasumaseru","en":"let (someone) rest  (休ませる)","pos":"v"}],"sentences":[{"en":"Please let me do it.","jp":"やらせて ください。","romaji":"yarasete kudasai.","hint":""},{"en":"Sorry to keep you waiting.","jp":"またせて ごめん。","romaji":"matasete gomen.","hint":""},{"en":"Let me think about it.","jp":"かんがえさせて。","romaji":"kangaesasete.","hint":""},{"en":"The teacher made the students write.","jp":"せんせいは がくせいに かかせた。","romaji":"sensei wa gakusei ni kakaseta.","hint":""},{"en":"Let me pay today.","jp":"きょうは はらわせて。","romaji":"kyou wa harawasete.","hint":""},{"en":"Let the kids rest.","jp":"こどもを やすませて。","romaji":"kodomo o yasumasete.","hint":""}]},{"id":"causative-passive","section":"Things Happen to You","title":"Made to Do It (〜させられる)","grammar":"causative-passive 〜させられる","grammarNote":"Causative + passive = “was made to do (against my will)”. う-verbs often contract to 〜される: のむ→のまされる, またせる→またされる. のまされた = “I was made to drink.”","vocab":[{"jp":"またされる","romaji":"matasareru","en":"be made to wait  (待たされる)","pos":"v"},{"jp":"のまされる","romaji":"nomasareru","en":"be made to drink  (飲まされる)","pos":"v"},{"jp":"やらされる","romaji":"yarasareru","en":"be made to do","pos":"v"},{"jp":"べんきょうさせられる","romaji":"benkyou saserareru","en":"be made to study","pos":"v"},{"jp":"てつだわされる","romaji":"tetsudawasareru","en":"be made to help  (手伝わされる)","pos":"v"},{"jp":"のみかい","romaji":"nomikai","en":"drinking party","pos":"n"}],"sentences":[{"en":"I was made to wait an hour.","jp":"いちじかん またされた。","romaji":"ichi-jikan matasareta.","hint":""},{"en":"I was made to drink at the party.","jp":"のみかいで のまされた。","romaji":"nomikai de nomasareta.","hint":""},{"en":"I'm always made to do the work.","jp":"いつも しごとを やらされる。","romaji":"itsumo shigoto o yarasareru.","hint":""},{"en":"As a kid I was made to study.","jp":"こどものとき べんきょうさせられた。","romaji":"kodomo no toki benkyou saserareta.","hint":""},{"en":"I was made to help with the move.","jp":"ひっこしを てつだわされた。","romaji":"hikkoshi o tetsudawasareta.","hint":""}]},{"id":"should-supposed","section":"Explaining & Nuance","title":"Should / Supposed To (〜べき・〜はず)","grammar":"〜べきだ  ·  〜はずだ","grammarNote":"〜べきだ = “should / ought to” (strong advice): いくべきだ = “you should go.” 〜はずだ = “supposed to / must be (logically)”: くるはずだ = “he's supposed to come.” 〜はずがない = “there's no way …”.","vocab":[{"jp":"べき","romaji":"beki","en":"should / ought to","pos":"aux"},{"jp":"はず","romaji":"hazu","en":"supposed to / must be","pos":"n"},{"jp":"あやまる","romaji":"ayamaru","en":"apologize  (謝る)","pos":"v"},{"jp":"しっている","romaji":"shitte iru","en":"know  (知っている)","pos":"v"},{"jp":"つく","romaji":"tsuku","en":"arrive  (着く)","pos":"v"},{"jp":"もうすぐ","romaji":"mousugu","en":"soon","pos":"adv"}],"sentences":[{"en":"You should apologize.","jp":"あやまるべきだ。","romaji":"ayamaru beki da.","hint":""},{"en":"He's supposed to know.","jp":"かれは しっているはずだ。","romaji":"kare wa shitte iru hazu da.","hint":""},{"en":"The train should arrive soon.","jp":"でんしゃは もうすぐ つくはず。","romaji":"densha wa mousugu tsuku hazu.","hint":""},{"en":"There's no way that's true.","jp":"そんなはずが ない。","romaji":"sonna hazu ga nai.","hint":""},{"en":"We should have left earlier.","jp":"もっと はやく でるべきだった。","romaji":"motto hayaku deru beki datta.","hint":""}]},{"id":"even-though","section":"Explaining & Nuance","title":"Even Though / No Matter (〜のに・〜ても)","grammar":"〜のに  ·  〜ても","grammarNote":"〜のに = “even though / despite”, often with frustration: べんきょうしたのに おちた = “I studied, yet I failed.” 〜ても = “even if / no matter”: いくら〜ても = “no matter how much …”.","vocab":[{"jp":"のに","romaji":"noni","en":"even though / despite","pos":"conj"},{"jp":"ても","romaji":"temo","en":"even if","pos":"conj"},{"jp":"いくら","romaji":"ikura","en":"no matter how much","pos":"adv"},{"jp":"がんばる","romaji":"ganbaru","en":"try hard  (頑張る)","pos":"v"},{"jp":"おちる","romaji":"ochiru","en":"fail / fall  (落ちる)","pos":"v"},{"jp":"ねむい","romaji":"nemui","en":"sleepy  (眠い)","pos":"adj"}],"sentences":[{"en":"I studied, yet I failed.","jp":"べんきょうしたのに、おちた。","romaji":"benkyou shita noni, ochita.","hint":""},{"en":"It's expensive, yet not tasty.","jp":"たかいのに、おいしくない。","romaji":"takai noni, oishikunai.","hint":""},{"en":"No matter how much I sleep, I'm sleepy.","jp":"いくら ねても、ねむい。","romaji":"ikura netemo, nemui.","hint":""},{"en":"Even if it rains, I'll go.","jp":"あめでも、いく。","romaji":"ame demo, iku.","hint":""},{"en":"Even if you try hard, it's no use.","jp":"がんばっても、むりだ。","romaji":"ganbattemo, muri da.","hint":""}]},{"id":"you-ni","section":"Explaining & Nuance","title":"Came to / Make a Point Of (〜ようになる・〜ようにする)","grammar":"〜ようになる  ·  〜ようにする","grammarNote":"〜ようになる = a change over time: came to (be able to) — はなせるようになった = “I became able to speak.” 〜ようにする = make an effort / a point of — あるくようにする = “I make a point of walking.”","vocab":[{"jp":"ようになる","romaji":"you ni naru","en":"come to (be able to)","pos":"aux"},{"jp":"ようにする","romaji":"you ni suru","en":"make a point of","pos":"aux"},{"jp":"なれる","romaji":"nareru","en":"get used to  (慣れる)","pos":"v"},{"jp":"まいにち","romaji":"mainichi","en":"every day","pos":"n"},{"jp":"あまいもの","romaji":"amai mono","en":"sweets","pos":"n"},{"jp":"せいかつ","romaji":"seikatsu","en":"life / daily living","pos":"n"}],"sentences":[{"en":"I became able to speak Japanese.","jp":"にほんごが はなせるようになった。","romaji":"nihongo ga hanaseru you ni natta.","hint":""},{"en":"I make a point of walking every day.","jp":"まいにち あるくようにしている。","romaji":"mainichi aruku you ni shite iru.","hint":""},{"en":"I came to understand kanji.","jp":"かんじが わかるようになった。","romaji":"kanji ga wakaru you ni natta.","hint":""},{"en":"I'm trying not to eat sweets.","jp":"あまいものを たべないようにしている。","romaji":"amai mono o tabenai you ni shite iru.","hint":""},{"en":"I've gotten used to life here.","jp":"ここの せいかつに なれた。","romaji":"koko no seikatsu ni nareta.","hint":""}]},{"id":"wake","section":"Explaining & Nuance","title":"That's Why / Not That (〜わけだ・〜わけではない)","grammar":"〜わけだ  ·  〜わけではない","grammarNote":"〜わけだ = “that's why / so it follows”: だから たかいわけだ = “so that's why it's expensive.” 〜わけではない／〜わけじゃない = “it's not that / not necessarily”: きらいなわけじゃない = “it's not that I dislike it.”","vocab":[{"jp":"わけ","romaji":"wake","en":"reason / the case","pos":"n"},{"jp":"だから","romaji":"dakara","en":"that's why / so","pos":"conj"},{"jp":"つまり","romaji":"tsumari","en":"in other words","pos":"conj"},{"jp":"きらい","romaji":"kirai","en":"dislike","pos":"adj"},{"jp":"はんたい","romaji":"hantai","en":"opposed / against  (反対)","pos":"n"},{"jp":"いそがしい","romaji":"isogashii","en":"busy","pos":"adj"}],"sentences":[{"en":"So that's why it's expensive.","jp":"だから たかいわけだ。","romaji":"dakara takai wake da.","hint":""},{"en":"It's not that I dislike it.","jp":"きらいなわけじゃない。","romaji":"kirai na wake ja nai.","hint":""},{"en":"It's not that I don't understand.","jp":"わからないわけじゃない。","romaji":"wakaranai wake ja nai.","hint":""},{"en":"It's not that I'm against it.","jp":"はんたいなわけじゃない。","romaji":"hantai na wake ja nai.","hint":""},{"en":"He didn't come — so it means he's busy.","jp":"こなかった。つまり いそがしいわけだ。","romaji":"konakatta. tsumari isogashii wake da.","hint":""}]}]},{"id":"L7","name":"Level 7","title":"Master","lessons":[{"id":"sonkeigo","section":"Keigo & Politeness","title":"Honorifics — Elevating Others (尊敬語)","grammar":"尊敬語 — respectful verbs","grammarNote":"Sonkeigo raises the person you're speaking to or about. Special verbs: いる/くる/いく→いらっしゃる, する→なさる, いう→おっしゃる, みる→ごらんになる, たべる/のむ→めしあがる.","vocab":[{"jp":"いらっしゃる","romaji":"irassharu","en":"be / come / go  (honorific)","pos":"v"},{"jp":"なさる","romaji":"nasaru","en":"do  (honorific)","pos":"v"},{"jp":"おっしゃる","romaji":"ossharu","en":"say  (honorific)","pos":"v"},{"jp":"ごらんになる","romaji":"goran ni naru","en":"see / look  (honorific)","pos":"v"},{"jp":"めしあがる","romaji":"meshiagaru","en":"eat / drink  (honorific)","pos":"v"},{"jp":"どちら","romaji":"dochira","en":"where / which  (polite)","pos":"n"}],"sentences":[{"en":"What is your name?","jp":"おなまえは なんと おっしゃいますか。","romaji":"onamae wa nan to osshaimasu ka.","hint":""},{"en":"Where are you going?","jp":"どちらへ いらっしゃいますか。","romaji":"dochira e irasshaimasu ka.","hint":""},{"en":"Please go ahead and eat.","jp":"どうぞ めしあがってください。","romaji":"douzo meshiagatte kudasai.","hint":""},{"en":"Have you seen this?","jp":"これを ごらんに なりましたか。","romaji":"kore o goran ni narimashita ka.","hint":""},{"en":"What would you like to do?","jp":"どう なさいますか。","romaji":"dou nasaimasu ka.","hint":""}]},{"id":"kenjougo","section":"Keigo & Politeness","title":"Humble Forms — Lowering Yourself (謙譲語)","grammar":"謙譲語 — humble verbs","grammarNote":"Kenjougo lowers your own actions before someone of higher status. いく/くる→まいる, いう→もうす, する→いたす, みる→はいけんする, きく/たずねる→うかがう, もらう/たべる→いただく.","vocab":[{"jp":"まいる","romaji":"mairu","en":"go / come  (humble)  (参る)","pos":"v"},{"jp":"もうす","romaji":"mousu","en":"say / be called  (humble)  (申す)","pos":"v"},{"jp":"いたす","romaji":"itasu","en":"do  (humble)  (致す)","pos":"v"},{"jp":"はいけんする","romaji":"haiken suru","en":"see / look  (humble)  (拝見する)","pos":"v"},{"jp":"うかがう","romaji":"ukagau","en":"ask / visit  (humble)  (伺う)","pos":"v"},{"jp":"いただく","romaji":"itadaku","en":"receive / accept  (humble)","pos":"v"}],"sentences":[{"en":"I'm Tanaka.","jp":"たなかと もうします。","romaji":"tanaka to moushimasu.","hint":""},{"en":"I'll take care of it.","jp":"わたしが いたします。","romaji":"watashi ga itashimasu.","hint":""},{"en":"May I take a look?","jp":"はいけんしても よろしいですか。","romaji":"haiken shite mo yoroshii desu ka.","hint":""},{"en":"I'll visit you tomorrow.","jp":"あした うかがいます。","romaji":"ashita ukagaimasu.","hint":""},{"en":"Thank you, I'll gladly accept it.","jp":"ありがたく いただきます。","romaji":"arigataku itadakimasu.","hint":""},{"en":"I'll come right away.","jp":"すぐに まいります。","romaji":"sugu ni mairimasu.","hint":""}]},{"id":"business-keigo","section":"Keigo & Politeness","title":"Polite Requests (〜ていただけますか)","grammar":"〜ていただけますか  ·  おそれいりますが","grammarNote":"The softest way to ask: 〜ていただけますか／〜ていただけませんか = “could you possibly …?” Soften further with おそれいりますが = “I'm sorry to trouble you, but …”. かしこまりました = “certainly / understood.”","vocab":[{"jp":"いただけますか","romaji":"itadakemasu ka","en":"could you …?","pos":"aux"},{"jp":"おそれいりますが","romaji":"osore irimasu ga","en":"sorry to trouble you, but…","pos":"expr"},{"jp":"しょうしょう","romaji":"shoushou","en":"a moment / a little  (少々)","pos":"adv"},{"jp":"おまちください","romaji":"omachi kudasai","en":"please wait  (polite)","pos":"expr"},{"jp":"かしこまりました","romaji":"kashikomarimashita","en":"certainly / understood","pos":"expr"},{"jp":"へんじ","romaji":"henji","en":"reply  (返事)","pos":"n"}],"sentences":[{"en":"Could you wait a moment?","jp":"しょうしょう おまちいただけますか。","romaji":"shoushou omachi itadakemasu ka.","hint":""},{"en":"Sorry to trouble you, but could you tell me?","jp":"おそれいりますが、おしえていただけますか。","romaji":"osore irimasu ga, oshiete itadakemasu ka.","hint":""},{"en":"Certainly.","jp":"かしこまりました。","romaji":"kashikomarimashita.","hint":""},{"en":"I look forward to your reply.","jp":"おへんじを おまちしております。","romaji":"ohenji o omachi shite orimasu.","hint":""},{"en":"Please wait just a moment.","jp":"しょうしょう おまちください。","romaji":"shoushou omachi kudasai.","hint":""}]},{"id":"zaru-o-enai","section":"Native Connectives","title":"Can't Help But (〜ざるを得ない・〜ずにはいられない)","grammar":"〜ざるを得ない  ·  〜ずにはいられない","grammarNote":"〜ざるを得ない = “have no choice but to …” (formal, reluctant): みとめざるを得ない = “I have to admit it.” 〜ずにはいられない = “can't help …ing”: わらわずにはいられない = “I can't help laughing.” (する→せざる／せずに)","vocab":[{"jp":"ざるをえない","romaji":"zaru o enai","en":"have no choice but to","pos":"aux"},{"jp":"ずにはいられない","romaji":"zu ni wa irarenai","en":"can't help …ing","pos":"aux"},{"jp":"みとめる","romaji":"mitomeru","en":"admit / acknowledge  (認める)","pos":"v"},{"jp":"あきらめる","romaji":"akirameru","en":"give up  (諦める)","pos":"v"},{"jp":"わらう","romaji":"warau","en":"laugh  (笑う)","pos":"v"},{"jp":"ちゅうし","romaji":"chuushi","en":"cancellation  (中止)","pos":"n"}],"sentences":[{"en":"I have no choice but to give up.","jp":"あきらめざるを得ない。","romaji":"akiramezaru o enai.","hint":""},{"en":"I have to admit he's right.","jp":"かれが ただしいと みとめざるを得ない。","romaji":"kare ga tadashii to mitomezaru o enai.","hint":""},{"en":"I can't help laughing.","jp":"わらわずには いられない。","romaji":"warawazu ni wa irarenai.","hint":""},{"en":"I can't help worrying.","jp":"しんぱいせずには いられない。","romaji":"shinpai sezu ni wa irarenai.","hint":""},{"en":"Given the rain, we had no choice but to cancel.","jp":"あめなので、ちゅうしせざるを得なかった。","romaji":"ame nanode, chuushi sezaru o enakatta.","hint":""}]},{"id":"ni-oite","section":"Native Connectives","title":"In / On the Occasion Of (〜において・〜にあたって)","grammar":"〜において  ·  〜にあたって","grammarNote":"Formal/written. 〜において = “in / at / in the field of”: かいぎにおいて = “at the meeting.” 〜にあたって = “on the occasion of / when undertaking”: しゅっぱつにあたって = “on departing.”","vocab":[{"jp":"において","romaji":"ni oite","en":"in / at / in the field of","pos":"conj"},{"jp":"にあたって","romaji":"ni atatte","en":"on the occasion of","pos":"conj"},{"jp":"かいぎ","romaji":"kaigi","en":"meeting  (会議)","pos":"n"},{"jp":"しゃかい","romaji":"shakai","en":"society  (社会)","pos":"n"},{"jp":"しゅっぱつ","romaji":"shuppatsu","en":"departure  (出発)","pos":"n"},{"jp":"きょういく","romaji":"kyouiku","en":"education  (教育)","pos":"n"}],"sentences":[{"en":"Opinions were exchanged at the meeting.","jp":"かいぎにおいて いけんが でた。","romaji":"kaigi ni oite iken ga deta.","hint":""},{"en":"In modern society, English is essential.","jp":"げんだいしゃかいにおいて、えいごは ひっすだ。","romaji":"gendai shakai ni oite, eigo wa hissu da.","hint":""},{"en":"On starting work, I greeted everyone.","jp":"しごとを はじめるにあたって、あいさつした。","romaji":"shigoto o hajimeru ni atatte, aisatsu shita.","hint":""},{"en":"Please take care on your departure.","jp":"しゅっぱつにあたって きをつけてください。","romaji":"shuppatsu ni atatte ki o tsukete kudasai.","hint":""},{"en":"This matters in education.","jp":"きょういくにおいて たいせつだ。","romaji":"kyouiku ni oite taisetsu da.","hint":""}]},{"id":"monono","section":"Native Connectives","title":"Although / That Said (〜ものの・〜とはいえ)","grammar":"〜ものの  ·  〜とはいえ","grammarNote":"〜ものの = “although / even though” (formal): やくそくしたものの、いけなかった = “although I promised, I couldn't go.” 〜とはいえ = “that said / even though”: ふゆとはいえ、あたたかい = “even though it's winter, it's warm.”","vocab":[{"jp":"ものの","romaji":"mono no","en":"although","pos":"conj"},{"jp":"とはいえ","romaji":"to wa ie","en":"that said / even though","pos":"conj"},{"jp":"やくそく","romaji":"yakusoku","en":"promise  (約束)","pos":"n"},{"jp":"ふゆ","romaji":"fuyu","en":"winter  (冬)","pos":"n"},{"jp":"さんせい","romaji":"sansei","en":"agreement / approval  (賛成)","pos":"n"},{"jp":"たより","romaji":"tayori","en":"reliance  (頼り)","pos":"n"},{"jp":"あたたかい","romaji":"atatakai","en":"warm","pos":"adj"}],"sentences":[{"en":"Although I promised, I couldn't go.","jp":"やくそくしたものの、いけなかった。","romaji":"yakusoku shita mono no, ikenakatta.","hint":""},{"en":"Even though it's winter, it's warm today.","jp":"ふゆとはいえ、きょうは あたたかい。","romaji":"fuyu to wa ie, kyou wa atatakai.","hint":""},{"en":"It's convenient, that said, I'm not used to it yet.","jp":"べんりとはいえ、まだ なれない。","romaji":"benri to wa ie, mada narenai.","hint":""},{"en":"Although I understand, I can't agree.","jp":"わかるものの、さんせいできない。","romaji":"wakaru mono no, sansei dekinai.","hint":""},{"en":"Even though he's young, he's reliable.","jp":"わかいとはいえ、たよりに なる。","romaji":"wakai to wa ie, tayori ni naru.","hint":""}]},{"id":"kagiri","section":"Native Connectives","title":"As Far As / While (〜かぎり・〜つつ)","grammar":"〜かぎり  ·  〜つつ  ·  〜にほかならない","grammarNote":"〜かぎり = “as far as / as long as”: しるかぎり = “as far as I know.” 〜つつ = formal “while”: しりつつ = “while knowing.” 〜にほかならない = “is nothing other than”: どりょくのけっかにほかならない = “it's nothing but the result of effort.”","vocab":[{"jp":"かぎり","romaji":"kagiri","en":"as far as / as long as  (限り)","pos":"conj"},{"jp":"つつ","romaji":"tsutsu","en":"while  (formal)","pos":"conj"},{"jp":"にほかならない","romaji":"ni hokanaranai","en":"is nothing other than","pos":"aux"},{"jp":"どりょく","romaji":"doryoku","en":"effort  (努力)","pos":"n"},{"jp":"けっか","romaji":"kekka","en":"result  (結果)","pos":"n"},{"jp":"せいこう","romaji":"seikou","en":"success  (成功)","pos":"n"}],"sentences":[{"en":"As far as I know, it's true.","jp":"しるかぎり、ほんとうだ。","romaji":"shiru kagiri, hontou da.","hint":""},{"en":"As long as I'm alive, I'll keep trying.","jp":"いきているかぎり、がんばる。","romaji":"ikite iru kagiri, ganbaru.","hint":""},{"en":"Knowing it's bad, I still can't stop.","jp":"わるいと しりつつ、やめられない。","romaji":"warui to shiritsutsu, yamerarenai.","hint":""},{"en":"Success is nothing but the result of effort.","jp":"せいこうは どりょくの けっかに ほかならない。","romaji":"seikou wa doryoku no kekka ni hokanaranai.","hint":""},{"en":"As far as I can see, there's no problem.","jp":"みるかぎり、もんだいない。","romaji":"miru kagiri, mondai nai.","hint":""}]}]}]};
